/**
 * Teamstärke aus dem FIFA-Wert: je Liga linear zwischen dem stärksten und schwächsten Klub,
 * auf die Stärkespanne dieser Liga umgerechnet. Die Abstände bleiben wie bei FIFA.
 */
const FIFA_STRENGTH = (() => {
  const m = {};
  Object.keys(FIFA27).forEach((id) => {
    const vals = Object.values(FIFA27[id]);
    const lo = Math.min(...vals);
    const hi = Math.max(...vals);
    const [top, bot] = LEAGUE_BY_ID[id].range;
    Object.entries(FIFA27[id]).forEach(([name, v]) => {
      m[name] = Math.round(bot + ((v - lo) / Math.max(1, hi - lo)) * (top - bot));
    });
  });
  return m;
})();

function defaultStrengths(leagueId, n) {
  const l = LEAGUE_BY_ID[leagueId];
  const [hi, lo] = l ? l.range : [55, 35];
  return Array.from({ length: n }, (_, i) => Math.round(hi - ((hi - lo) * i) / (n - 1)));
}

function nextLabel(label) {
  const m = /^(\d{4})\/(\d{2})$/.exec(String(label).trim());
  if (!m) return label;
  const y = Number(m[1]) + 1;
  return `${y}/${String((y + 1) % 100).padStart(2, "0")}`;
}

/** Nach jeder Saison ändert sich die Stärke jeder Mannschaft um höchstens diesen Betrag. */
const DRIFT_MAX = 5;

function driftValue(v) {
  const delta = Math.floor(Math.random() * (2 * DRIFT_MAX + 1)) - DRIFT_MAX;
  return Math.max(1, Math.min(99, Math.round(Number(v) || 0) + delta));
}

/** Kader auf eine neue Teamstärke (höchstens ±DRIFT_MAX) verschieben. */
function driftSquad(squad) {
  return squad ? scaleSquadTo(squad, driftValue(squadStrength(squad))) : squad;
}

/**
 * Neue Stärken auf Knopfdruck: jeder Kader der genannten Ligen ändert sich um höchstens ±DRIFT_MAX. Beim Saisonwechsel
 * bleiben die Stärken unverändert, bis dieser Knopf gedrückt wird. Für Deutschland (`mitDe`) zählen auch der
 * Regionalliga-Topf und die ausländischen Europapokal-Teilnehmer ohne eigene Liga.
 */
function driftLeagues(d, ids, mitDe) {
  const active = { ...d.active };
  ids.forEach((id) => {
    const s = d.active[id];
    if (!s) return;
    const squads = s.squads.map(driftSquad);
    active[id] = { ...s, squads, strengths: squads.map(squadStrength) };
  });
  const out = { ...d, active };
  if (mitDe) {
    out.euro = {
      ...d.euro,
      teams: Object.fromEntries(Object.entries(d.euro.teams).map(([id, list]) => [
        id, list.map((t) => (euroIsLive(t) ? t : { ...t, strength: driftValue(t.strength) }))])),
    };
  }
  return out;
}

function newSeason(teams, strengths, label, start, squads) {
  const kader = squads && squads.length === teams.length ? squads : makeSquads(teams, strengths);
  return {
    label,
    start: start || "2026-08-14",
    teams: [...teams],
    squads: kader,
    strengths: kader.map(squadStrength),
    seed: Math.floor(Math.random() * 1e9),
    results: {},
  };
}

/** Vereine, deren echte Kaderliste bereits in einen Speicherstand übernommen wurde. */
const REAL_NAMES = Object.keys(REAL_SQUADS);

function freshData() {
  const active = {};
  LEAGUES.forEach((l) => {
    const std = defaultStrengths(l.id, l.teams.length);
    const werte = l.teams.map((n, i) => (FIFA_STRENGTH[n] != null ? FIFA_STRENGTH[n] : std[i]));
    active[l.id] = newSeason(l.teams, werte, "2026/27", defaultStart(l.id, "2026/27"));
  });
  [...ENGLAND, ...SPAIN, ...ITALY, ...FRANCE, ...WORLD_LEAGUES].forEach((l) => {
    active[l.id] = newSeason(l.teams, l.teams.map((n) => TEAM_START[n]), "2026/27", defaultStart(l.id, "2026/27"));
  });
  return { active, cup: null, facup: null, copa: null, coppa: null, coupe: null, ...WORLD_CUP_NULLS, tourn: null, nationStr: {}, news: [], clubInfo: {}, playerInfo: {}, matchInfo: {}, favorites: [], history: [], drawBias: 0, surpriseBias: 1, realSquads: [...REAL_NAMES], logos: {}, euro: freshEuro(),
    regional: [] };
}

/** Alte Speicherstände nachrüsten, damit nichts verloren geht. */
/** Vereine, die früher unter einem anderen Namen geführt wurden. */
const UMBENENNUNG = { "SSV Jeddeloh": "SSV Jeddeloh II" };

function normalize(d0) {
  if (!d0 || !d0.active) return freshData();
  const alias = (n) => UMBENENNUNG[n] || n;
  const d = {
    ...d0,
    active: Object.fromEntries(Object.entries(d0.active).map(([id, s]) =>
      [id, s && Array.isArray(s.teams) ? { ...s, teams: s.teams.map(alias) } : s])),
    regional: Array.isArray(d0.regional) ? d0.regional.map((c) => ({ ...c, name: alias(c.name) })) : d0.regional,
  };
  const out = { euro: normEuro(d.euro), logos: d.logos && typeof d.logos === "object" ? d.logos : {}, active: {}, cup: d.cup || null, facup: d.facup || null, copa: d.copa || null, coppa: d.coppa || null, coupe: d.coupe || null, ...Object.fromEntries(WORLD_KEYS.map((k) => [WORLD_CUP_KEY[k], d[WORLD_CUP_KEY[k]] || null])), tourn: d.tourn && Array.isArray(d.tourn.teams) && Array.isArray(d.tourn.groups) ? d.tourn : null, nationStr: normObj(d.nationStr), news: normNews(d.news), clubInfo: normObj(d.clubInfo), playerInfo: normObj(d.playerInfo), matchInfo: normObj(d.matchInfo), favorites: Array.isArray(d.favorites) ? d.favorites.map(String) : [], history: d.history || [], drawBias: Number(d.drawBias) || 0, surpriseBias: d.surpriseBias == null ? 1 : Number(d.surpriseBias) };
  // Vereine, für die inzwischen eine echte Kaderliste dazugekommen ist, bekommen sie
  // nachträglich — aber jeder nur einmal, damit eigene Änderungen erhalten bleiben.
  out.regional = Array.isArray(d.regional) ? d.regional : []; // alter Regionalliga-Topf, nur noch aufbewahrt
  out.legacyLower = d.legacyLower || (d.active.bl4 || d.active.bl5 ? { bl4: d.active.bl4 || null, bl5: d.active.bl5 || null } : null);
  const applied = Array.isArray(d.realSquads) ? [...d.realSquads] : [];
  const nachzutragen = REAL_NAMES.filter((n) => applied.indexOf(n) < 0);
  out.realSquads = [...applied, ...nachzutragen];
  LEAGUE_IDS.forEach((id) => {
    const s = d.active[id];
    if (!s) {
      const l = LEAGUE_BY_ID[id];
      out.active[id] = newSeason(l.teams, defaultStrengths(id, l.teams.length), "2026/27", defaultStart(id, "2026/27"));
      return;
    }
    const strengths =
      Array.isArray(s.strengths) && s.strengths.length === s.teams.length
        ? s.strengths.map((v) => Number(v) || 1)
        : defaultStrengths(id, s.teams.length);
    const squads = Array.isArray(s.squads) && s.squads.length === s.teams.length
      ? s.squads.map((q, i) => fixSquad(q, s.teams[i], strengths[i]))
      : makeSquads(s.teams, strengths);
    const frisch = squads.map((q, i) =>
      nachzutragen.indexOf(s.teams[i]) >= 0 ? makeSquad(s.teams[i], strengths[i]) : q);
    out.active[id] = {
      ...s, squads: frisch, strengths: frisch.map(squadStrength),
      start: s.start || defaultStart(id, s.label),
    };
  });
  // England: ältere Speicherstände kennen die Premier League noch nicht.
  [...ENGLAND, ...SPAIN, ...ITALY, ...FRANCE, ...WORLD_LEAGUES].forEach((l) => {
    const s = d.active[l.id];
    if (!s || !Array.isArray(s.teams)) {
      out.active[l.id] = newSeason(l.teams, l.teams.map((n) => TEAM_START[n]), "2026/27", defaultStart(l.id, "2026/27"));
      return;
    }
    const strengths = Array.isArray(s.strengths) && s.strengths.length === s.teams.length
      ? s.strengths.map((v) => Number(v) || 1) : s.teams.map((n) => TEAM_START[n] || 60);
    const squads = Array.isArray(s.squads) && s.squads.length === s.teams.length
      ? s.squads.map((q, i) => fixSquad(q, s.teams[i], strengths[i])) : makeSquads(s.teams, strengths);
    out.active[l.id] = { ...s, squads, strengths: squads.map(squadStrength), start: s.start || defaultStart(l.id, s.label) };
  });
  // Alte Spielstände: der neue Unterbau ist frisch angelegt; wer schon in einer höheren Liga spielt, wird ersetzt.
  // Ersatz sind die Klubs der früheren 4./5. Liga (samt Kader), die sonst nirgends mehr spielen.
  if (!d.active.rl_n && out.legacyLower) {
    const taken = new Set();
    LEAGUE_IDS.forEach((x) => { if (out.active[x] && !DE_LOW_BY_ID[x]) out.active[x].teams.forEach((t) => taken.add(t)); });
    const alle = new Set();
    DE_LOW.forEach((l) => l.teams.forEach((t) => alle.add(t)));
    const spare = [];
    ["bl4", "bl5"].forEach((k) => {
      const o = out.legacyLower[k];
      if (o && o.teams) o.teams.forEach((t, i) => { if (!taken.has(t) && !alle.has(t)) spare.push({ name: t, squad: o.squads && o.squads[i] }); });
    });
    DE_LOW.forEach((l) => {
      const s = out.active[l.id];
      const dup = s.teams.map((t) => taken.has(t));
      if (!dup.some(Boolean)) return;
      const teams = [];
      const squads = [];
      s.teams.forEach((t, i) => {
        if (!dup[i]) { teams.push(t); squads.push(s.squads[i]); return; }
        const r = spare.shift();
        if (r) { teams.push(r.name); squads.push(r.squad || makeSquad(r.name, s.strengths[i])); }
      });
      if (teams.length % 2) { teams.pop(); squads.pop(); }
      out.active[l.id] = newSeason(teams, teams.map((_, i) => squadStrength(squads[i])), s.label, s.start, squads);
    });
  }
  EURO_COMPS.forEach((c) => {
    const r = out.euro.runs[c.id];
    if (r && r.teams.some((t) => !t.squad)) {
      out.euro.runs[c.id] = { ...r, teams: r.teams.map((t) => (t.squad ? t : { ...t, squad: euroSquadFor(t, t.strength, out.active) })) };
    }
  });
  return out;
}

const STORAGE_KEY = "ligarechner:v2";

let LOAD_FAILED = false;

async function loadState() {
  let raw = null;
  try {
    if (!window.storage) return null;
    const r = await window.storage.get(STORAGE_KEY);
    if (!r || !r.value) return null;
    raw = r.value;
    return normalize(JSON.parse(raw));
  } catch (e) {
    // Lässt sich der Stand nicht lesen, bleibt eine Kopie erhalten, damit nichts verloren geht.
    LOAD_FAILED = true;
    try { if (raw && window.storage) await window.storage.set(STORAGE_KEY + ":rettung", raw); } catch (e2) { /* ignorieren */ }
    return null;
  }
}

const UI_KEY = STORAGE_KEY + ":ui";

/** Ansichtsstand (Tab, Spieltag, Pokalrunde, Europa-Auswahl) getrennt vom Datenstand. */
async function loadUi() {
  try {
    if (!window.storage) return null;
    const r = await window.storage.get(UI_KEY);
    return r && r.value ? JSON.parse(r.value) : null;
  } catch (e) {
    return null;
  }
}

async function persistUi(ui) {
  try {
    if (window.storage) await window.storage.set(UI_KEY, JSON.stringify(ui));
  } catch (e) { /* Ansichtsstand ist nicht kritisch */ }
}

async function persist(data) {
  try {
    if (!window.storage) return false;
    return !!(await window.storage.set(STORAGE_KEY, JSON.stringify(data)));
  } catch (e) {
    return false;
  }
}

/* ================================================================== */
/*  DFB-Pokal                                                         */
/* ================================================================== */

const CUP_ROUNDS = ["1. Runde", "2. Runde", "Achtelfinale", "Viertelfinale", "Halbfinale", "Finale"];

function cupWinner(g) {
  if (g.hg === "" || g.ag === "" || g.hg == null || g.ag == null) return null;
  const h = Number(g.hg);
  const a = Number(g.ag);
  if (!Number.isFinite(h) || !Number.isFinite(a)) return null;
  if (h > a) return g.h;
  if (a > h) return g.a;
  if (g.pen === "h") return g.h;
  if (g.pen === "a") return g.a;
  return null;
}

function roundComplete(round) {
  return round.games.every((g) => cupWinner(g) !== null);
}

/** Paarungen ziehen. Der Klub aus der tieferen Liga bekommt Heimrecht. */
function drawPairs(teams, seed) {
  const rnd = mulberry32(seed);
  const pool = shuffle(teams, rnd);
  const games = [];
  while (pool.length > 1) {
    const x = pool.shift();
    const y = pool.shift();
    const [home, away] =
      x.tier > y.tier ? [x, y] : y.tier > x.tier ? [y, x] : rnd() < 0.5 ? [x, y] : [y, x];
    games.push({ h: home, a: away, hg: "", ag: "", pen: null });
  }
  return games;
}

/** Erste Runde: jeder Amateur bekommt einen Profi und Heimrecht. */
function drawFirstRound(field, seed) {
  const rnd = mulberry32(seed);
  const pros = shuffle(field.filter((t) => t.tier <= 1), rnd);
  const amateurs = shuffle(field.filter((t) => t.tier >= 2), rnd);
  const games = [];
  const n = Math.min(pros.length, amateurs.length);
  for (let i = 0; i < n; i++) {
    games.push({ h: amateurs[i], a: pros[i], hg: "", ag: "", pen: null });
  }
  return [...games, ...drawPairs([...pros.slice(n), ...amateurs.slice(n)], seed + 7)];
}

/* ---------------- Torschützen ---------------- */

/** Wie wahrscheinlich ein Spieler trifft: Position zählt am meisten, Stärke hilft. */
const TOR_GEWICHT = { TW: 0.2, ABW: 2.5, MF: 7, ST: 20 };

function torGewichte(squad) {
  const spieler = (squad && squad.p) || [];
  return spieler.map((pl) => {
    const pos = TOR_GEWICHT[pl.p] || 5;
    const bank = pl.b ? 0.28 : 1;
    const st = Math.max(1, Number(pl.s) || 40);
    return pos * bank * (st / 60);
  });
}

/** Zufällige Torschützen für eine Anzahl Tore, mit Minuten. */
function makeScorers(squad, anzahl, rnd) {
  const spieler = (squad && squad.p) || [];
  if (!spieler.length || anzahl <= 0) return [];
  const w = torGewichte(squad);
  const summe = w.reduce((a, b) => a + b, 0);
  const tore = [];
  for (let i = 0; i < anzahl; i++) {
    let x = rnd() * summe, k = 0;
    while (k < w.length - 1 && x > w[k]) { x -= w[k]; k++; }
    const min = 1 + Math.floor(rnd() * 90);
    tore.push({ n: spieler[k].n, m: min });
  }
  return tore.sort((a, b) => a.m - b.m);
}

/** Tore beider Mannschaften zu einer Liste zusammenführen. */
function goalsFor(squadH, squadA, hg, ag, seed) {
  const rnd = mulberry32(seed >>> 0);
  const h = makeScorers(squadH, hg, rnd).map((t) => ({ ...t, s: "h" }));
  const a = makeScorers(squadA, ag, rnd).map((t) => ({ ...t, s: "a" }));
  return [...h, ...a].sort((x, y) => x.m - y.m);
}

/** Torjägerliste aus einer Ligasaison. */
function scorerTable(season, fixtures) {
  const zaehler = new Map();
  Object.keys(season.results || {}).forEach((key) => {
    const r = season.results[key];
    if (!r || !Array.isArray(r.g)) return;
    const [mi, gi] = key.split(":").map(Number);
    const paar = fixtures[mi] && fixtures[mi][gi];
    if (!paar) return;
    r.g.forEach((t) => {
      const team = season.teams[t.s === "h" ? paar[0] : paar[1]];
      const id = `${t.n}||${team}`;
      const e = zaehler.get(id) || { name: t.n, team, tore: 0 };
      e.tore++; zaehler.set(id, e);
    });
  });
  return [...zaehler.values()].sort((a, b) => b.tore - a.tore || a.name.localeCompare(b.name));
}

/** Torjägerliste aus dem Pokal. */
function cupScorerTable(cup) {
  const zaehler = new Map();
  (cup && cup.rounds ? cup.rounds : []).forEach((r) => {
    r.games.forEach((g) => {
      if (!Array.isArray(g.tore)) return;
      g.tore.forEach((t) => {
        const team = (t.s === "h" ? g.h : g.a).name;
        const id = `${t.n}||${team}`;
        const e = zaehler.get(id) || { name: t.n, team, tore: 0 };
        e.tore++; zaehler.set(id, e);
      });
    });
  });
  return [...zaehler.values()].sort((a, b) => b.tore - a.tore || a.name.localeCompare(b.name));
}

function newCup(active, amateurs, label) {
  const field = [];
  PRO_IDS.forEach((id, tier) => {
    const s = active[id];
    s.teams.forEach((name, i) => field.push({
      name, strength: Number(s.strengths[i]) || 1, tier,
      form: (s.squads && s.squads[i] && s.squads[i].f) || "4-4-2",
      squad: (s.squads && s.squads[i]) || null,
    }));
  });
  // Amateure aus den Regionalligen bringen ihren Kader mit.
  const unten = DE_RL.map((l) => active[l.id]).filter(Boolean);
  amateurs.forEach((a) => {
    let kader = null;
    unten.forEach((u) => {
      const k = u.teams.indexOf(a.name);
      if (k >= 0 && u.squads && u.squads[k]) kader = u.squads[k];
    });
    field.push({
      name: a.name, strength: Number(a.strength) || 1, tier: 3,
      squad: kader || a.squad || makeSquad(a.name, Number(a.strength) || 20),
    });
  });
  const seed = Math.floor(Math.random() * 1e9);
  return {
    label,
    seed,
    rounds: [{ name: CUP_ROUNDS[0], games: drawFirstRound(field, seed) }],
  };
}

/* ---------------- FA Cup ---------------- */

const FA_ROUNDS = ["1. Runde", "2. Runde", "3. Runde", "4. Runde", "5. Runde", "Viertelfinale", "Halbfinale", "Finale"];
const FA_ACCENT = "#D9634C";

/**
 * FA Cup mit den 92 Profiklubs: In der 1. Runde spielen 16 Klubs aus League One und League Two, die übrigen
 * 32 steigen in der 2. Runde ein, Premier League und Championship in der 3. Runde (dann 64 Mannschaften).
 * Heimrecht hat der Klub aus der tieferen Liga, bei Gleichstand gibt es sofort Elfmeterschießen (keine Wiederholungsspiele).
 */
function newFaCup(active, label) {
  const field = [];
  ENG_IDS.forEach((id, tier) => {
    const s = active[id];
    s.teams.forEach((name, i) => field.push({
      name, strength: Number(s.strengths[i]) || 1, tier,
      form: (s.squads && s.squads[i] && s.squads[i].f) || "4-4-2",
      squad: (s.squads && s.squads[i]) || null,
    }));
  });
  const seed = Math.floor(Math.random() * 1e9);
  const rnd = mulberry32(seed);
  const unten = shuffle(field.filter((t) => t.tier >= 2), rnd);
  const oben = field.filter((t) => t.tier <= 1);
  return {
    label, seed, names: FA_ROUNDS,
    joiners: { 1: unten.slice(16), 2: oben },
    rounds: [{ name: FA_ROUNDS[0], games: drawPairs(unten.slice(0, 16), seed) }],
  };
}

const COPA_ROUNDS = ["1. Runde", "Runde der 64", "Runde der 32", "Achtelfinale", "Viertelfinale", "Halbfinale", "Finale"];
const COPA_ACCENT = "#E0B13F";

/**
 * Copa del Rey mit allen pokalberechtigten Profiklubs (ohne Reservemannschaften, 75 Klubs): In der 1. Runde spielen
 * die schwächsten 22 Klubs, alle übrigen steigen in der Runde der 64 ein. Heimrecht hat der Klub aus der tieferen
 * Liga, bei Gleichstand gibt es sofort Elfmeterschießen, das Finale zählt als neutraler Platz.
 */
function newCopa(active, label) {
  const field = [];
  ES_IDS.forEach((id) => {
    const s = active[id];
    s.teams.forEach((name, i) => {
      if (ES_RESERVE.has(name)) return;
      field.push({
        name, strength: Number(s.strengths[i]) || 1, tier: id === "ll" ? 0 : id === "sd" ? 1 : 2,
        form: (s.squads && s.squads[i] && s.squads[i].f) || "4-4-2",
        squad: (s.squads && s.squads[i]) || null,
      });
    });
  });
  const seed = Math.floor(Math.random() * 1e9);
  const schwach = [...field].sort((a, b) => a.strength - b.strength || a.name.localeCompare(b.name, "de"));
  const spiele = Math.max(1, field.length - 64);
  return {
    label, seed, names: COPA_ROUNDS,
    joiners: { 1: schwach.slice(2 * spiele) },
    rounds: [{ name: COPA_ROUNDS[0], games: drawPairs(schwach.slice(0, 2 * spiele), seed) }],
  };
}

const COPPA_ROUNDS = ["1. Runde", "Runde der 32", "Achtelfinale", "Viertelfinale", "Halbfinale", "Finale"];
const COPPA_ACCENT = "#4FA8E8";

/**
 * Coppa Italia mit allen 20 Klubs der Serie A, allen 20 der Serie B und den 4 stärksten Klubs der Serie C
 * (ohne Reservemannschaften, 44 Klubs): In der 1. Runde spielen die schwächsten 24 Klubs, alle übrigen steigen
 * in der Runde der 32 ein. Heimrecht hat der Klub aus der tieferen Liga, bei Gleichstand gibt es sofort
 * Elfmeterschießen, das Finale zählt als neutraler Platz.
 */
function newCoppa(active, label) {
  const field = [];
  const add = (id, tier, list) => list.forEach((i) => {
    const s = active[id];
    field.push({
      name: s.teams[i], strength: Number(s.strengths[i]) || 1, tier,
      form: (s.squads && s.squads[i] && s.squads[i].f) || "4-4-2",
      squad: (s.squads && s.squads[i]) || null,
    });
  });
  add("sa", 0, active.sa.teams.map((_, i) => i));
  add("sb", 1, active.sb.teams.map((_, i) => i).filter((i) => !IT_RESERVE.has(active.sb.teams[i])));
  const c = [];
  ["sca", "scb", "scc"].forEach((id) => active[id].teams.forEach((n, i) => {
    if (!IT_RESERVE.has(n)) c.push({ id, i, st: Number(active[id].strengths[i]) || 1, n });
  }));
  c.sort((a, b) => b.st - a.st || a.n.localeCompare(b.n, "de"));
  c.slice(0, 4).forEach((x) => add(x.id, 2, [x.i]));
  const seed = Math.floor(Math.random() * 1e9);
  const schwach = [...field].sort((a, b) => a.strength - b.strength || a.name.localeCompare(b.name, "de"));
  const spiele = Math.max(1, field.length - 32);
  return {
    label, seed, names: COPPA_ROUNDS,
    joiners: { 1: schwach.slice(2 * spiele) },
    rounds: [{ name: COPPA_ROUNDS[0], games: drawPairs(schwach.slice(0, 2 * spiele), seed) }],
  };
}

const COUPE_ROUNDS = ["1. Runde", "Runde der 32", "Achtelfinale", "Viertelfinale", "Halbfinale", "Finale"];
const COUPE_ACCENT = "#E4554D";

/**
 * Coupe de France mit allen 54 Klubs der Ligue 1, Ligue 2 und Ligue 3: In der 1. Runde spielen die schwächsten 44 Klubs,
 * die übrigen 10 steigen in der Runde der 32 ein. Heimrecht hat der Klub aus der tieferen Liga, bei Gleichstand gibt es
 * sofort Elfmeterschießen, das Finale zählt als neutraler Platz.
 */
function newCoupe(active, label) {
  const field = [];
  FR_IDS.forEach((id, tier) => {
    const s = active[id];
    s.teams.forEach((name, i) => {
      field.push({
        name, strength: Number(s.strengths[i]) || 1, tier,
        form: (s.squads && s.squads[i] && s.squads[i].f) || "4-4-2",
        squad: (s.squads && s.squads[i]) || null,
      });
    });
  });
  const seed = Math.floor(Math.random() * 1e9);
  const schwach = [...field].sort((a, b) => a.strength - b.strength || a.name.localeCompare(b.name, "de"));
  const spiele = Math.max(1, field.length - 32);
  return {
    label, seed, names: COUPE_ROUNDS,
    joiners: { 1: schwach.slice(2 * spiele) },
    rounds: [{ name: COUPE_ROUNDS[0], games: drawPairs(schwach.slice(0, 2 * spiele), seed) }],
  };
}

/** Pokal eines weiteren Landes: alle Klubs aller Ligen, bei Bedarf mit Vorrunde der schwächsten Klubs. */
function worldRoundName(size) {
  return size === 2 ? "Finale" : size === 4 ? "Halbfinale" : size === 8 ? "Viertelfinale" : size === 16 ? "Achtelfinale" : `Runde der ${size}`;
}

function newWorldCup(active, c, label) {
  const field = [];
  c.leagues.forEach((lg, tier) => {
    const s = active[lg.id];
    s.teams.forEach((name, i) => {
      if (c.reserveSet.has(name)) return;
      field.push({
        name, strength: Number(s.strengths[i]) || 1, tier,
        form: (s.squads && s.squads[i] && s.squads[i].f) || "4-4-2",
        squad: (s.squads && s.squads[i]) || null,
      });
    });
  });
  const seed = Math.floor(Math.random() * 1e9);
  const n = field.length;
  let P = 2;
  while (P * 2 <= n) P *= 2;
  const names = [];
  for (let size = P; size >= 2; size /= 2) names.push(worldRoundName(size));
  const schwach = [...field].sort((a, b) => a.strength - b.strength || a.name.localeCompare(b.name, "de"));
  if (n === P) return { label, seed, names, joiners: {}, rounds: [{ name: names[0], games: drawPairs(field, seed) }] };
  const spiele = n - P;
  const allNames = ["Vorrunde", ...names];
  return {
    label, seed, names: allNames,
    joiners: { 1: schwach.slice(2 * spiele) },
    rounds: [{ name: "Vorrunde", games: drawPairs(schwach.slice(0, 2 * spiele), seed) }],
  };
}

