const NATION_BY_NAME = Object.fromEntries(NATIONS.map((n) => [n.name, n]));

/** Flaggen-Emoji aus dem Ländercode (England, Schottland, Wales mit Subdivision-Flagge). */
function flagEmoji(cc) {
  const tags = { "GB-ENG": "gbeng", "GB-SCT": "gbsct", "GB-WLS": "gbwls" };
  if (tags[cc]) return String.fromCodePoint(0x1f3f4, ...[...tags[cc]].map((ch) => 0xe0000 + ch.charCodeAt(0)), 0xe007f);
  if (cc === "GB-NIR") return "🇬🇧";
  return String.fromCodePoint(...[...cc].map((ch) => 0x1f1e6 + ch.charCodeAt(0) - 65));
}

function Flag({ cc }) {
  return <span className="lr-flag" aria-hidden="true">{cc ? flagEmoji(cc) : ""}</span>;
}

const TOURN_PRESETS = {
  em: { name: "Europameisterschaft", n: 24, groups: 6, thirds: 4, ko: ["Achtelfinale", "Viertelfinale", "Halbfinale", "Finale"] },
  wm: { name: "Weltmeisterschaft", n: 48, groups: 12, thirds: 8, ko: ["Runde der 32", "Achtelfinale", "Viertelfinale", "Halbfinale", "Finale"] },
  k16: { name: "Nationen-Turnier", n: 16, groups: 4, thirds: 0, ko: ["Viertelfinale", "Halbfinale", "Finale"] },
  k8: { name: "Mini-Turnier", n: 8, groups: 2, thirds: 0, ko: ["Halbfinale", "Finale"] },
};
const GROUP_FIX = [[[0, 1], [2, 3]], [[0, 2], [3, 1]], [[3, 0], [1, 2]]];
const groupLetter = (i) => String.fromCharCode(65 + i);

/** Nationalmannschaft als Teilnehmer: Stärke aus der Liste (oder eigener Wert), Kader echt oder erzeugt. */
function nationTeam(nat, overrides) {
  const strength = Number((overrides || {})[nat.name]) || nat.strength;
  const squad = makeSquad(nat.name, strength);
  return { name: nat.name, cc: nat.cc, strength, squad, form: squad.f || "4-4-2", tier: 0 };
}

/** Neues Turnier: Töpfe nach Stärke, jede Gruppe bekommt aus jedem Topf eine Mannschaft. */
function newTournament(presetKey, name, label, teams) {
  const pre = TOURN_PRESETS[presetKey];
  const seed = Math.floor(Math.random() * 1e9);
  const rnd = mulberry32(seed);
  const sorted = [...teams].sort((a, b) => b.strength - a.strength || a.name.localeCompare(b.name, "de"));
  const G = pre.groups;
  const pots = [];
  for (let k = 0; k < 4; k++) pots.push(shuffle(sorted.slice(k * G, (k + 1) * G).map((_, i) => k * G + i), rnd));
  const groups = [];
  for (let g = 0; g < G; g++) groups.push({ name: groupLetter(g), idx: pots.map((p) => p[g]), results: {} });
  return { id: newId("t"), name, preset: presetKey, label, seed, teams: sorted, groups, ko: null };
}

const groupTeams = (t, g) => g.idx.map((i) => t.teams[i].name);
const groupRows = (t, g) => computeTable(groupTeams(t, g), GROUP_FIX, g.results);
const groupDone = (g) => GROUP_FIX.every((md, mi) => md.every((_, gi) => parsedResult(g.results, mi, gi)));
const tournGroupsDone = (t) => t.groups.every(groupDone);

/** Weiter: Gruppensieger, Zweite und die besten Dritten. */
function tournQualifiers(t) {
  const pre = TOURN_PRESETS[t.preset];
  const win = [];
  const run = [];
  const thirds = [];
  t.groups.forEach((g) => {
    const rows = groupRows(t, g);
    win.push(t.teams[g.idx[rows[0].idx]]);
    run.push(t.teams[g.idx[rows[1].idx]]);
    thirds.push({ team: t.teams[g.idx[rows[2].idx]], r: rows[2], g: g.name });
  });
  thirds.sort((a, b) => b.r.pkt - a.r.pkt || b.r.diff - a.r.diff || b.r.t - a.r.t || a.team.name.localeCompare(b.team.name, "de"));
  const best = thirds.slice(0, pre.thirds);
  return { win, run, thirds: best.map((x) => x.team), allThirds: thirds };
}

/** K.-o.-Runde auslosen; Paarungen aus derselben Gruppe möglichst vermeiden. */
function tournBuildKo(t) {
  const q = tournQualifiers(t);
  const teams = [...q.win, ...q.run, ...q.thirds];
  const groupOf = {};
  t.groups.forEach((g) => g.idx.forEach((i) => { groupOf[t.teams[i].name] = g.name; }));
  const names = TOURN_PRESETS[t.preset].ko;
  let games = null;
  for (let k = 0; k < 60 && !games; k++) {
    const gs = drawPairs(teams, t.seed + 97 * (k + 1));
    if (k === 59 || gs.every((g) => groupOf[g.h.name] !== groupOf[g.a.name])) games = gs;
  }
  return { label: t.label, seed: t.seed, names, joiners: {}, rounds: [{ name: names[0], games }] };
}

/** Alle gespielten Partien des Turniers (für die Torjägerliste). */
function tournGames(t) {
  const out = [];
  t.groups.forEach((g) => {
    GROUP_FIX.forEach((md, mi) => md.forEach(([h, a], gi) => {
      const r = g.results[`${mi}:${gi}`];
      if (r) out.push({ sc: r.sc, heim: t.teams[g.idx[h]].name, gast: t.teams[g.idx[a]].name });
    }));
  });
  if (t.ko) out.push(...cupGames(t.ko));
  return out;
}

function TournamentTab({ data, setData }) {
  const { openPlayer } = useContext(ClubCtx);
  const t = data.tourn;
  const [preset, setPreset] = useState("em");
  const [tname, setTname] = useState("");
  const [picked, setPicked] = useState(null);
  const [view, setView] = useState("groups");
  const [m3, setM3] = useState(null);
  const [koRound, setKoRound] = useState(0);
  const [ask, setAsk] = useState("");
  const drawShare = DRAW_SHARE[data.drawBias || 0] != null ? DRAW_SHARE[data.drawBias || 0] : 0;
  const surprise = data.surpriseBias == null ? 1 : Number(data.surpriseBias);
  const nations = useMemo(() => [...NATIONS].map((n) => ({ ...n, strength: Number((data.nationStr || {})[n.name]) || n.strength })).sort((a, b) => b.strength - a.strength), [data.nationStr]);
  const pre = TOURN_PRESETS[preset];
  const sel = picked && picked.preset === preset ? picked.names : nations.slice(0, pre.n).map((n) => n.name);
  const setT = (fn) => setData((d) => (d.tourn ? { ...d, tourn: fn(d.tourn) } : d));

  const start = () => {
    const list = sel.map((nm) => nationTeam(NATION_BY_NAME[nm], data.nationStr));
    setData((d) => ({ ...d, tourn: newTournament(preset, tname.trim() || `${pre.name} ${new Date().getFullYear() + (preset === "wm" ? 4 : 2)}`, String(new Date().getFullYear()), list) }));
    setView("groups"); setKoRound(0);
  };
  const toggle = (nm) => {
    const cur = new Set(sel);
    if (cur.has(nm)) cur.delete(nm); else if (cur.size < pre.n) cur.add(nm);
    setPicked({ preset, names: [...cur] });
  };

  if (!t) {
    return (
      <div className="lr-wrap" id="tourn-tab">
        <h2 className="lr-sec-h">Neues Turnier</h2>
        <p className="lr-hint">Wähle ein Turnierformat und die Mannschaften. Die Gruppen werden nach Stärke in Töpfen ausgelost, danach folgt die K.-o.-Phase. Alle Ergebnisse, Torschützen und Karten kannst du selbst eintragen.</p>
        <div className="lr-k-form">
          <label className="lr-k-field"><span>Format</span>
            <select className="lr-team-in" id="tn-preset" value={preset} onChange={(e) => { setPreset(e.target.value); setPicked(null); }}>
              {Object.entries(TOURN_PRESETS).map(([k, p]) => <option key={k} value={k}>{p.name} ({p.n} Teams)</option>)}
            </select>
          </label>
          <KField label="Name" id="tn-name" value={tname} placeholder={pre.name} onChange={setTname} />
        </div>
        <div className="lr-k-card"><small>Mannschaften ({sel.length} von {pre.n})</small>
          <div className="lr-k-nations">
            {nations.map((n) => (
              <button key={n.name} className="lr-k-nat" data-on={sel.indexOf(n.name) >= 0 ? "1" : "0"} onClick={() => toggle(n.name)}>
                <Flag cc={n.cc} />{n.name}<small>{n.strength}</small>
              </button>
            ))}
          </div>
        </div>
        <div className="lr-modal-foot" style={{ justifyContent: "flex-start" }}>
          <button className="lr-btn lr-btn-p" id="tn-start" disabled={sel.length !== pre.n} onClick={start}>Turnier auslosen</button>
        </div>
      </div>
    );
  }

  const preT = TOURN_PRESETS[t.preset];
  const sim = (sh, sa, neutral, tH, tA) => simulateMatch(sh, sa, neutral, drawShare, surprise, tH, tA);
  const T = (i) => t.teams[i];
  const side = (x) => ({ name: x.name, strength: x.strength, squad: x.squad });

  const setGroupResult = (gIdx, key, patch) => setT((tt) => ({
    ...tt, groups: tt.groups.map((g, k) => {
      if (k !== gIdx) return g;
      const cur = g.results[key] || { h: "", a: "" };
      const e = { ...cur, ...patch };
      if (e.h === "" && e.a === "") { const r = { ...g.results }; delete r[key]; return { ...g, results: r }; }
      e.sc = trimGoals(e.sc, Number(e.h) || 0, Number(e.a) || 0);
      return { ...g, results: { ...g.results, [key]: e } };
    }),
  }));
  const simGroupGame = (gIdx, mi, gi) => {
    const g = t.groups[gIdx];
    const [h, a] = GROUP_FIX[mi][gi];
    const A = T(g.idx[h]);
    const B = T(g.idx[a]);
    const [hg, ag] = sim(A.strength, B.strength, true, formationTilt(A.form), formationTilt(B.form));
    setGroupResult(gIdx, `${mi}:${gi}`, { h: String(hg), a: String(ag), sc: makeGoals(A.squad, B.squad, hg, ag) });
  };
  const simAllGroups = () => setT((tt) => ({
    ...tt, groups: tt.groups.map((g) => {
      const results = { ...g.results };
      GROUP_FIX.forEach((md, mi) => md.forEach(([h, a], gi) => {
        if (parsedResult(results, mi, gi)) return;
        const A = tt.teams[g.idx[h]];
        const B = tt.teams[g.idx[a]];
        const [hg, ag] = sim(A.strength, B.strength, true, formationTilt(A.form), formationTilt(B.form));
        results[`${mi}:${gi}`] = { h: String(hg), a: String(ag), sc: makeGoals(A.squad, B.squad, hg, ag) };
      }));
      return { ...g, results };
    }),
  }));
  const open3dGroup = (gIdx, mi, gi) => {
    const g = t.groups[gIdx];
    const [h, a] = GROUP_FIX[mi][gi];
    const A = T(g.idx[h]);
    const B = T(g.idx[a]);
    const r = g.results[`${mi}:${gi}`] || { h: "", a: "" };
    setM3({
      home: side(A), away: side(B), hg: r.h, ag: r.a, sc: r.sc,
      sim: () => sim(A.strength, B.strength, true, formationTilt(A.form), formationTilt(B.form)),
      onTake: (hg, ag, sc) => setGroupResult(gIdx, `${mi}:${gi}`, { h: String(hg), a: String(ag), sc }),
    });
  };

  const drawKo = () => setT((tt) => ({ ...tt, ko: tournBuildKo(tt) }));
  const editRound = (ri, fn) => setT((tt) => ({ ...tt, ko: { ...tt.ko, rounds: tt.ko.rounds.map((r, i) => (i === ri ? fn(r) : r)).slice(0, ri + 1) } }));
  const setKoScore = (ri, gi, side2, raw) => {
    const v = raw.replace(/[^0-9]/g, "").slice(0, 2);
    editRound(ri, (r) => ({ ...r, games: r.games.map((g, k) => {
      if (k !== gi) return g;
      const n = { ...g, [side2 === "h" ? "hg" : "ag"]: v, pen: null };
      n.sc = trimGoals(n.sc, Number(n.hg) || 0, Number(n.ag) || 0);
      return n;
    }) }));
  };
  const setKoPen = (ri, gi, who) => editRound(ri, (r) => ({ ...r, games: r.games.map((g, k) => (k === gi ? { ...g, pen: g.pen === who ? null : who } : g)) }));
  const simKoGame = (ri, gi) => editRound(ri, (r) => ({ ...r, games: r.games.map((g, k) => {
    if (k !== gi) return g;
    const [hg, ag] = sim(g.h.strength, g.a.strength, true, formationTilt(g.h.form), formationTilt(g.a.form));
    return { ...g, hg: String(hg), ag: String(ag), sc: makeGoals(g.h.squad, g.a.squad, hg, ag), pen: hg === ag ? shootout(g.h.strength, g.a.strength) : null };
  }) }));
  const simKoRound = (ri) => editRound(ri, (r) => ({ ...r, games: r.games.map((g) => {
    if (cupWinner(g)) return g;
    const [hg, ag] = sim(g.h.strength, g.a.strength, true, formationTilt(g.h.form), formationTilt(g.a.form));
    return { ...g, hg: String(hg), ag: String(ag), sc: makeGoals(g.h.squad, g.a.squad, hg, ag), pen: hg === ag ? shootout(g.h.strength, g.a.strength) : null };
  }) }));
  const open3dKo = (ri, gi) => {
    const g = t.ko.rounds[ri].games[gi];
    setM3({
      home: side(g.h), away: side(g.a), hg: g.hg, ag: g.ag, sc: g.sc, note: g.pen ? `Elfmeterschießen: ${g.pen === "h" ? g.h.name : g.a.name}.` : "",
      sim: () => sim(g.h.strength, g.a.strength, true, formationTilt(g.h.form), formationTilt(g.a.form)),
      onTake: (hg, ag, sc) => editRound(ri, (r) => ({ ...r, games: r.games.map((x, k) => (k === gi ? { ...x, hg: String(hg), ag: String(ag), sc, pen: hg === ag ? shootout(x.h.strength, x.a.strength) : null } : x)) })),
    });
  };
  const nextRound = () => setT((tt) => {
    const cur = tt.ko.rounds[tt.ko.rounds.length - 1];
    if (!roundComplete(cur) || tt.ko.rounds.length >= tt.ko.names.length) return tt;
    const winners = cur.games.map((g) => cupWinner(g));
    return { ...tt, ko: { ...tt.ko, rounds: [...tt.ko.rounds, { name: tt.ko.names[tt.ko.rounds.length], games: drawPairs(winners, tt.seed + tt.ko.rounds.length * 31) }] } };
  });

  const koLast = t.ko ? t.ko.rounds[t.ko.rounds.length - 1] : null;
  const champion = koLast && koLast.name === "Finale" && koLast.games[0] ? cupWinner(koLast.games[0]) : null;
  const runnerUp = champion ? (champion === koLast.games[0].h ? koLast.games[0].a : koLast.games[0].h) : null;
  const groupsDone = tournGroupsDone(t);
  const scorers = scorerList(tournGames(t), new Map()).slice(0, 10);
  const ri = t.ko ? Math.min(koRound, t.ko.rounds.length - 1) : 0;

  const finish = () => {
    setData((d) => {
      const tt = d.tourn;
      const entry = {
        ...cupHistoryEntry({ ...d, active: {}, tournko: tt.ko }, "tournko"),
        leagueId: "tournko", leagueName: tt.name, label: tt.label,
        groups: tt.groups.map((g) => ({ name: g.name, table: groupRows(tt, g).map((r) => ({ name: r.name, pos: r.pos, sp: r.sp, pkt: r.pkt, t: r.t, gt: r.gt })) })),
        id: `tourn-${tt.id}`,
      };
      return { ...d, tourn: null, history: [entry, ...d.history] };
    });
    setAsk("");
  };

  return (
    <div className="lr-wrap" id="tourn-tab">
      {m3 && <Match3D spec={m3} onClose={() => setM3(null)} />}
      <div className="lr-k-newshead">
        <div>
          <h2 className="lr-sec-h" style={{ margin: 0 }}>{t.name}</h2>
          <span className="lr-k-sub">{preT.n} Mannschaften · {t.groups.length} Gruppen · {t.ko ? `K.-o.-Phase: ${koLast.name}` : groupsDone ? "Gruppenphase beendet" : "Gruppenphase"}</span>
        </div>
        <div className="lr-spacer" />
        {!groupsDone && <button className="lr-btn lr-btn-sm" id="tn-sim-groups" onClick={simAllGroups}>Gruppenphase simulieren</button>}
        {groupsDone && !t.ko && <button className="lr-btn lr-btn-sm lr-btn-p" id="tn-draw-ko" onClick={drawKo}>K.-o.-Phase auslosen</button>}
        {champion && <button className="lr-btn lr-btn-sm lr-btn-p" id="tn-finish" onClick={finish}>Turnier abschließen</button>}
        {ask === "drop"
          ? <><span className="lr-status">Turnier verwerfen?</span><button className="lr-btn lr-btn-sm" onClick={() => setAsk("")}>Nein</button><button className="lr-btn lr-btn-sm lr-btn-p" id="tn-drop-ok" onClick={() => { setData((d) => ({ ...d, tourn: null })); setAsk(""); }}>Ja</button></>
          : <button className="lr-btn lr-btn-sm" id="tn-drop" onClick={() => setAsk("drop")}>Verwerfen</button>}
      </div>

      {champion && (
        <div className="lr-champ-box" id="tn-champ" style={{ marginBottom: 14 }}>
          <div><small>Turniersieger</small>
            <div className="disp"><Flag cc={champion.cc} /> {champion.name}</div>
            <small>Finalgegner: {runnerUp.name}</small></div>
        </div>
      )}

      <div className="lr-k-chips" role="group" aria-label="Ansicht">
        <button className="lr-k-chip" id="tn-v-groups" data-on={view === "groups" ? "1" : "0"} onClick={() => setView("groups")}>Gruppen</button>
        <button className="lr-k-chip" id="tn-v-ko" data-on={view === "ko" ? "1" : "0"} onClick={() => setView("ko")} disabled={!t.ko}>K.-o.-Runde</button>
        <button className="lr-k-chip" id="tn-v-top" data-on={view === "top" ? "1" : "0"} onClick={() => setView("top")}>Torjäger</button>
      </div>

      {view === "groups" && (
        <div className="lr-k-groups" id="tn-groups">
          {t.groups.map((g, gIdx) => {
            const rows = groupRows(t, g);
            return (
              <div className="lr-k-card" key={g.name} data-g={g.name}>
                <small>Gruppe {g.name}</small>
                <table className="lr-tbl lr-k-gt">
                  <thead><tr><th>#</th><th>Mannschaft</th><th>Sp</th><th>Diff</th><th>Pkt</th></tr></thead>
                  <tbody>
                    {rows.map((r, i) => {
                      const tm = T(g.idx[r.idx]);
                      const advance = i < 2 || (i === 2 && preT.thirds > 0);
                      return (
                        <tr key={r.name} data-adv={advance ? "1" : "0"}>
                          <td>{r.pos}</td>
                          <td className="name"><Flag cc={tm.cc} />{r.name}</td>
                          <td>{r.sp}</td><td>{r.diff > 0 ? `+${r.diff}` : r.diff}</td><td className="pkt">{r.pkt}</td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
                {GROUP_FIX.map((md, mi) => md.map(([h, a], gi) => {
                  const A = T(g.idx[h]);
                  const B = T(g.idx[a]);
                  const r = g.results[`${mi}:${gi}`] || { h: "", a: "" };
                  const key = `${mi}:${gi}`;
                  return (
                    <div className="lr-k-tg" key={key} data-md={mi}>
                      <small>{mi + 1}</small>
                      <span className="r">{A.name}</span>
                      <ScoreBox value={r.h} team={A.name} onType={(v) => setGroupResult(gIdx, key, { h: v.replace(/[^0-9]/g, "").slice(0, 2) })} />
                      <span>:</span>
                      <ScoreBox value={r.a} team={B.name} onType={(v) => setGroupResult(gIdx, key, { a: v.replace(/[^0-9]/g, "").slice(0, 2) })} />
                      <span>{B.name}</span>
                      <button className="lr-sim" type="button" onClick={() => simGroupGame(gIdx, mi, gi)} title="Spiel simulieren">Sim</button>
                      <button className="lr-sim lr-3d" type="button" onClick={() => open3dGroup(gIdx, mi, gi)} title="In 3D ansehen">3D</button>
                    </div>
                  );
                }))}
              </div>
            );
          })}
        </div>
      )}

      {view === "ko" && t.ko && (
        <div id="tn-ko">
          <div className="lr-k-chips">
            {t.ko.rounds.map((r, i) => <button key={r.name} className="lr-k-chip" data-on={i === ri ? "1" : "0"} onClick={() => setKoRound(i)}>{r.name}</button>)}
          </div>
          {t.ko.rounds[ri].games.map((g, gi) => {
            const w = cupWinner(g);
            const drawn = g.hg !== "" && g.ag !== "" && Number(g.hg) === Number(g.ag);
            return (
              <div className="lr-k-tg lr-k-ko" key={gi}>
                <span className={`r ${w === g.h ? "lr-win" : w ? "lr-lose" : ""}`}><Flag cc={g.h.cc} />{g.h.name}</span>
                <ScoreBox value={g.hg} team={g.h.name} onType={(v) => setKoScore(ri, gi, "h", v)} />
                <span>:</span>
                <ScoreBox value={g.ag} team={g.a.name} onType={(v) => setKoScore(ri, gi, "a", v)} />
                <span className={w === g.a ? "lr-win" : w ? "lr-lose" : ""}><Flag cc={g.a.cc} />{g.a.name}</span>
                <button className="lr-sim" type="button" onClick={() => simKoGame(ri, gi)}>Sim</button>
                <button className="lr-sim lr-3d" type="button" onClick={() => open3dKo(ri, gi)}>3D</button>
                {drawn && (
                  <span className="lr-k-pen">Elfmeterschießen:
                    <button className="lr-k-chip" data-on={g.pen === "h" ? "1" : "0"} onClick={() => setKoPen(ri, gi, "h")}>{g.h.name}</button>
                    <button className="lr-k-chip" data-on={g.pen === "a" ? "1" : "0"} onClick={() => setKoPen(ri, gi, "a")}>{g.a.name}</button>
                  </span>
                )}
              </div>
            );
          })}
          <div className="lr-modal-foot" style={{ justifyContent: "flex-start" }}>
            <button className="lr-btn lr-btn-sm" id="tn-sim-round" onClick={() => simKoRound(ri)}>Runde simulieren</button>
            {ri === t.ko.rounds.length - 1 && roundComplete(koLast) && koLast.name !== "Finale" && (
              <button className="lr-btn lr-btn-sm lr-btn-p" id="tn-next" onClick={() => { nextRound(); setKoRound(ri + 1); }}>Nächste Runde auslosen</button>
            )}
          </div>
        </div>
      )}

      {view === "top" && (
        <div className="lr-k-card" id="tn-top"><small>Torschützen</small>
          {!scorers.length && <span className="lr-hint">Noch keine Torschützen.</span>}
          {scorers.map((x) => <div key={x.name} className="lr-k-row"><span>{x.name} <em>{x.verein}</em></span><b>{x.tore}</b></div>)}
        </div>
      )}
    </div>
  );
}

function NationsTab({ data, setData }) {
  const [q, setQ] = useState("");
  const [open, setOpen] = useState(null);
  const list = [...NATIONS].map((n) => ({ ...n, strength: Number((data.nationStr || {})[n.name]) || n.strength }))
    .filter((n) => !q.trim() || n.name.toLowerCase().indexOf(q.trim().toLowerCase()) >= 0)
    .sort((a, b) => b.strength - a.strength);
  const setStr = (name, raw) => {
    const v = raw.replace(/[^0-9]/g, "").slice(0, 2);
    setData((d) => ({ ...d, nationStr: { ...(d.nationStr || {}), [name]: v === "" ? "" : Math.max(1, Math.min(99, Number(v))) } }));
  };
  return (
    <div className="lr-wrap" id="nations-tab">
      <div className="lr-k-newshead">
        <h2 className="lr-sec-h" style={{ margin: 0 }}>Nationen</h2>
        <div className="lr-spacer" />
        <input className="lr-team-in" id="nations-q" style={{ maxWidth: 240 }} placeholder="Nation suchen" value={q} onChange={(e) => setQ(e.target.value)} aria-label="Nation suchen" />
      </div>
      <p className="lr-hint">Stärke und Kader der Nationalmannschaften. Die Stärke lässt sich ändern und gilt für neue Turniere.</p>
      <div className="lr-k-clubs">
        {list.map((n) => (
          <div className="lr-k-tile" key={n.name}>
            <button className="lr-k-link" style={{ flexDirection: "column" }} onClick={() => setOpen(n.name)}><Flag cc={n.cc} /><span>{n.name}</span></button>
            <input className="lr-str-in" value={n.strength} inputMode="numeric" aria-label={`Stärke ${n.name}`} onFocus={(e) => e.target.select()} onChange={(e) => setStr(n.name, e.target.value)} />
          </div>
        ))}
      </div>
      {open && <NationModal name={open} data={data} onClose={() => setOpen(null)} />}
    </div>
  );
}

function NationModal({ name, data, onClose }) {
  const n = NATION_BY_NAME[name];
  const strength = Number((data.nationStr || {})[name]) || n.strength;
  const squad = useMemo(() => makeSquad(name, strength), [name, strength]);
  return (
    <Modal onClose={onClose}>
      <div className="lr-k" id="nation-modal">
        <div className="lr-k-head"><span className="lr-flag-big"><Flag cc={n.cc} /></span>
          <div className="lr-k-title"><h2>{name}</h2><span className="lr-k-sub">Stärke {strength} · Aufstellung {squad.f}</span></div></div>
        {["TW", "ABW", "MF", "ST"].map((pos) => (
          <div className="lr-k-card" key={pos}><small>{POS_NAMES[pos]}</small>
            {playersOf(squad).filter((p) => p.p === pos).map((p) => <div className="lr-k-row" key={p.n}><span>{p.n}{p.b ? <em> Bank</em> : null}</span><b>{p.s}</b></div>)}
          </div>
        ))}
        <div className="lr-modal-foot"><button className="lr-btn" onClick={onClose}>Schließen</button></div>
      </div>
    </Modal>
  );
}

/* ---------------- Nachrichten, Vereins- und Spielerseiten, Spielberichte ---------------- */

const NEWS_CATS = ["Liga", "Verein", "Transfer", "Spielbericht", "Pokal & Europa", "Sonstiges"];
const LEAGUE_ALL_IDS = ALL_LEAGUE_IDS;
const SECTION_KEYS = ["de", "en", "es", "it", "fr", ...WORLD_KEYS, "nt"];

const todayISO = () => {
  const t = new Date();
  return `${t.getFullYear()}-${pad2(t.getMonth() + 1)}-${pad2(t.getDate())}`;
};
const newId = (p) => `${p}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`;
const normObj = (o) => (o && typeof o === "object" && !Array.isArray(o) ? o : {});

/** Artikel prüfen und mit Standardwerten auffüllen (alte Speicherstände haben keine). */
function normNews(list) {
  if (!Array.isArray(list)) return [];
  return list.filter((x) => x && (x.title || x.body)).map((x) => ({
    id: String(x.id || newId("a")),
    title: String(x.title || ""),
    teaser: String(x.teaser || ""),
    body: String(x.body || ""),
    date: String(x.date || todayISO()),
    cat: NEWS_CATS.indexOf(x.cat) >= 0 ? x.cat : "Sonstiges",
    section: SECTION_KEYS.indexOf(x.section) >= 0 ? x.section : "",
    team: String(x.team || ""),
    pinned: !!x.pinned,
    img: typeof x.img === "string" ? x.img : "",
  }));
}

function sectionOfLeagueId(id) {
  return SECTION_KEYS.find((sec) => COUNTRY[sec].ids.indexOf(id) >= 0) || "de";
}

/** Verein in den Ligen finden (Liga, Platz im Kader der Saison, Saison). */
function findClub(data, name) {
  for (let k = 0; k < LEAGUE_ALL_IDS.length; k++) {
    const id = LEAGUE_ALL_IDS[k];
    const s = data.active[id];
    const i = s ? s.teams.indexOf(name) : -1;
    if (i >= 0) return { id, i, s, lg: LEAGUE_BY_ID[id], sec: sectionOfLeagueId(id) };
  }
  return null;
}

/** Alle Vereine eines Abschnitts mit Liga und Tabellenplatz. */
function clubsOfSection(data, sec) {
  const out = [];
  COUNTRY[sec].ids.forEach((id) => {
    const s = data.active[id];
    if (!s) return;
    const rows = computeTable(s.teams, makeFixtures(s.teams.length, s.seed), s.results);
    const pos = {};
    rows.forEach((r) => { pos[r.idx] = r; });
    s.teams.forEach((name, i) => out.push({ name, id, lg: LEAGUE_BY_ID[id], i, pos: pos[i] ? pos[i].pos : i + 1, strength: s.strengths[i] }));
  });
  return out;
}

/** Kader eines Vereins: aus der Liga, sonst aus dem Europapokal oder neu erzeugt. */
function squadOfClub(data, name) {
  const c = findClub(data, name);
  if (c) return c.s.squads[c.i];
  for (const comp of EURO_COMPS) {
    const run = data.euro && data.euro.runs && data.euro.runs[comp.id];
    const t = run && run.teams.find((x) => x.name === name);
    if (t && t.squad) return t.squad;
  }
  let st = 40;
  EURO_COMPS.forEach((comp) => {
    const t = ((data.euro && data.euro.teams && data.euro.teams[comp.id]) || []).find((x) => x.name === name);
    if (t) st = Number(t.strength) || st;
  });
  return makeSquad(name, st);
}

/** Spieler suchen: Verein, Eintrag im Kader. */
function findPlayer(data, name) {
  for (let k = 0; k < LEAGUE_ALL_IDS.length; k++) {
    const s = data.active[LEAGUE_ALL_IDS[k]];
    if (!s) continue;
    for (let i = 0; i < s.teams.length; i++) {
      const q = s.squads[i];
      const idx = playersOf(q).findIndex((p) => p.n === name);
      if (idx >= 0) return { club: s.teams[i], pl: playersOf(q)[idx], leagueId: LEAGUE_ALL_IDS[k], squad: q };
    }
  }
  return null;
}

/** Tore eines Spielers in der Ligasaison seines Vereins: Spieltag, Gegner, Minute. */
function playerGoals(s, clubIdx, name) {
  const fx = makeFixtures(s.teams.length, s.seed);
  const out = [];
  Object.keys(s.results || {}).forEach((key) => {
    const [mi, gi] = key.split(":").map(Number);
    const pair = fx[mi] && fx[mi][gi];
    if (!pair || (pair[0] !== clubIdx && pair[1] !== clubIdx)) return;
    const home = pair[0] === clubIdx;
    ((s.results[key] || {}).sc || []).forEach((g) => {
      if ((g.p || "").trim() === name && g.t === (home ? "h" : "a")) out.push({ md: mi + 1, opp: s.teams[home ? pair[1] : pair[0]], m: g.m || 0, home });
    });
  });
  return out.sort((a, b) => a.md - b.md);
}

/** Alle Spiele eines Vereins in der Saison mit Datum und Ergebnis. */
function clubGames(s, clubIdx) {
  const fx = makeFixtures(s.teams.length, s.seed);
  const dates = matchdayDates(s.start, fx.length);
  const out = [];
  fx.forEach((round, mi) => round.forEach(([h, a], gi) => {
    if (h !== clubIdx && a !== clubIdx) return;
    const res = parsedResult(s.results, mi, gi);
    const home = h === clubIdx;
    out.push({ md: mi, gi, home, opp: home ? a : h, date: dates[mi], res: res ? (home ? res : [res[1], res[0]]) : null, hg: res ? res[0] : null, ag: res ? res[1] : null });
  }));
  return out;
}

/** Tabelle nach Heim-, Auswärts- oder Halbserienspielen. */
function partialTable(teams, fixtures, results, mode) {
  const rows = teams.map((name, i) => ({ idx: i, name, sp: 0, s: 0, u: 0, n: 0, t: 0, gt: 0, pkt: 0, form: [] }));
  const half = Math.ceil(fixtures.length / 2);
  fixtures.forEach((md, mi) => md.forEach(([h, a], gi) => {
    const res = parsedResult(results, mi, gi);
    if (!res) return;
    if (mode === "first" && mi >= half) return;
    if (mode === "second" && mi < half) return;
    const [hg, ag] = res;
    const add = (r, f, g) => {
      r.sp++; r.t += f; r.gt += g;
      if (f > g) { r.s++; r.pkt += 3; r.form.push("S"); } else if (f < g) { r.n++; r.form.push("N"); } else { r.u++; r.pkt++; r.form.push("U"); }
    };
    if (mode !== "away") add(rows[h], hg, ag);
    if (mode !== "home") add(rows[a], ag, hg);
  }));
  rows.forEach((r) => { r.diff = r.t - r.gt; r.form = r.form.slice(-5); });
  rows.sort((a, b) => b.pkt - a.pkt || b.diff - a.diff || b.t - a.t || a.name.localeCompare(b.name, "de"));
  rows.forEach((r, i) => { r.pos = i + 1; });
  return rows;
}

/** Spielberichte-Schlüssel: Liga, Saison, Spieltag und Spiel. */
const matchKey = (leagueId, label, md, gi) => `${leagueId}|${label}|${md}:${gi}`;

/** Suche nach Vereinen und Spielern in allen Ligen. */
function searchAll(data, query) {
  const q = query.trim().toLowerCase();
  if (q.length < 2) return { clubs: [], players: [] };
  const clubs = [];
  const players = [];
  LEAGUE_ALL_IDS.forEach((id) => {
    const s = data.active[id];
    if (!s) return;
    s.teams.forEach((t, i) => {
      if (t.toLowerCase().indexOf(q) >= 0) clubs.push({ name: t, lg: LEAGUE_BY_ID[id].name });
      if (players.length < 40) {
        playersOf(s.squads[i]).forEach((p) => {
          if (p.n && p.n.toLowerCase().indexOf(q) >= 0 && players.length < 40) players.push({ name: p.n, club: t, pos: p.p });
        });
      }
    });
  });
  return { clubs: clubs.slice(0, 12), players };
}

/** Meldungen, die sich automatisch aus den Ergebnissen ergeben (letzter gespielter Spieltag je Liga). */
function autoNews(data, sec) {
  const out = [];
  COUNTRY[sec].ids.forEach((id) => {
    const s = data.active[id];
    if (!s) return;
    const fx = makeFixtures(s.teams.length, s.seed);
    let last = -1;
    fx.forEach((round, mi) => { if (round.some((_, gi) => parsedResult(s.results, mi, gi))) last = mi; });
    if (last < 0) return;
    fx[last].forEach(([h, a], gi) => {
      const res = parsedResult(s.results, last, gi);
      if (!res) return;
      out.push({ leagueId: id, lg: LEAGUE_BY_ID[id].name, md: last, gi, h: s.teams[h], a: s.teams[a], hg: res[0], ag: res[1], sens: sensation(res[0], res[1], s.strengths[h], s.strengths[a]) });
    });
  });
  return out;
}

/** Überschrift zu einem Ergebnis wie in einer Meldung. */
function resultHeadline(r) {
  if (r.hg === r.ag) return `${r.h} und ${r.a} trennen sich ${r.hg}:${r.ag}`;
  const w = r.hg > r.ag ? r.h : r.a;
  const l = r.hg > r.ag ? r.a : r.h;
  const diff = Math.abs(r.hg - r.ag);
  const verb = diff >= 4 ? "überrollt" : diff >= 3 ? "fertigt ab" : diff === 1 ? "bezwingt" : "schlägt";
  return `${w} ${verb} ${l} ${Math.max(r.hg, r.ag)}:${Math.min(r.hg, r.ag)}`;
}

/**
 * Spieler wechselt den Verein: Kader und Stärken beider Klubs werden neu berechnet, dazu entsteht eine
 * Transfermeldung. Ein Klub braucht mindestens 15 Spieler, höchstens 25.
 */
function transferPlayer(d, name, toClub) {
  const from = findPlayer(d, name);
  const to = findClub(d, toClub);
  const fc = from ? findClub(d, from.club) : null;
  if (!from || !to || !fc || from.club === toClub) return d;
  if (playersOf(from.squad).length <= 15 || playersOf(to.s.squads[to.i]).length >= 25) return d;
  const active = { ...d.active };
  const setSquad = (c, fn) => {
    const s = active[c.id];
    const squads = s.squads.map((q, i) => (i === c.i ? fn(q) : q));
    active[c.id] = { ...s, squads, strengths: squads.map(squadStrength) };
  };
  setSquad(fc, (q) => autoLineup({ ...q, p: q.p.filter((x) => x.n !== name) }));
  setSquad(to, (q) => autoLineup({ ...q, p: [...q.p, { ...from.pl, b: true }] }));
  const article = {
    id: newId("a"), title: `${name} wechselt zu ${toClub}`, teaser: `${from.club} → ${toClub}`,
    body: `${name} (${POS_NAMES[from.pl.p] || from.pl.p}, Stärke ${from.pl.s}) verlässt ${from.club} und schließt sich ${toClub} an.`,
    date: todayISO(), cat: "Transfer", section: to.sec, team: toClub, pinned: false, img: "",
  };
  return { ...d, active, news: [article, ...(d.news || [])] };
}

const ClubCtx = createContext({ openClub: () => {}, openPlayer: () => {}, openMatch: () => {}, favorites: [] });

/** Vereinsname, der die Vereinsseite öffnet. */
function TeamLink({ name, children }) {
  const { openClub } = useContext(ClubCtx);
  return (
    <span className="lr-tl" role="link" tabIndex={0} title={`Vereinsseite ${name}`}
      onClick={(e) => { e.stopPropagation(); openClub(name); }}
      onKeyDown={(e) => { if (e.key === "Enter") { e.stopPropagation(); openClub(name); } }}>
      {children || name}
    </span>
  );
}

/** Spielername, der die Spielerseite öffnet. */
function PlayerLink({ name, children }) {
  const { openPlayer } = useContext(ClubCtx);
  return (
    <span className="lr-tl" role="link" tabIndex={0} title={`Spielerseite ${name}`}
      onClick={(e) => { e.stopPropagation(); openPlayer(name); }}
      onKeyDown={(e) => { if (e.key === "Enter") { e.stopPropagation(); openPlayer(name); } }}>
      {children || name}
    </span>
  );
}

const POS_NAMES = { TW: "Torwart", ABW: "Abwehr", MF: "Mittelfeld", ST: "Sturm" };
const lastName = (n) => String(n).trim().split(" ").slice(-1)[0];

/** Kleines Textfeld mit Beschriftung. */
function KField({ label, value, onChange, placeholder, type, id, wide }) {
  return (
    <label className={`lr-k-field${wide ? " wide" : ""}`}>
      <span>{label}</span>
      <input className="lr-team-in" id={id} type={type || "text"} value={value} placeholder={placeholder || ""}
        onChange={(e) => onChange(e.target.value)} />
    </label>
  );
}

/* ---- Vereinsseite ---- */

function ClubModal({ data, setData, name, onClose }) {
  const { openPlayer, openMatch, openArticle, newArticle, favorites } = useContext(ClubCtx);
  const club = findClub(data, name);
  const [tab, setTab] = useState("ueber");
  const saved = (data.clubInfo || {})[name] || {};
  const [info, setInfo] = useState({ trainer: saved.trainer || "", stadium: saved.stadium || "", founded: saved.founded || "", colors: saved.colors || "", president: saved.president || "", city: saved.city || "", note: saved.note || "" });
  const [flash, setFlash] = useState("");
  const squad = squadOfClub(data, name);
  const fav = favorites.indexOf(name) >= 0;
  const toggleFav = () => setData((d) => ({ ...d, favorites: fav ? d.favorites.filter((x) => x !== name) : [...d.favorites, name] }));

  const view = useMemo(() => {
    if (!club) return null;
    const { s, i } = club;
    const fx = makeFixtures(s.teams.length, s.seed);
    const rows = computeTable(s.teams, fx, s.results);
    const row = rows.find((r) => r.idx === i);
    const games = clubGames(s, i);
    const scorers = scorerList(seasonGames(s, fx), squadIndex([s])).filter((x) => x.verein === name);
    return { rows, row, games, scorers };
  }, [club && club.s, name]);

  const articles = (data.news || []).filter((a) => a.team === name).sort((a, b) => (b.date > a.date ? 1 : -1));
  const goalsOf = (pn) => (view ? (view.scorers.find((x) => x.name === pn) || { tore: 0 }).tore : 0);
  const byPos = {};
  playersOf(squad).forEach((p) => { (byPos[p.p] = byPos[p.p] || []).push(p); });
  const next = view ? view.games.find((g) => !g.res) : null;
  const lastPlayed = view ? [...view.games].reverse().find((g) => g.res) : null;

  const saveInfo = () => {
    setData((d) => ({ ...d, clubInfo: { ...(d.clubInfo || {}), [name]: { ...info } } }));
    setFlash("Gespeichert.");
    setTimeout(() => setFlash(""), 1800);
  };

  const tabs = [["ueber", "Übersicht"], ["spiele", "Spiele"], ["kader", "Kader"], ["news", `Nachrichten${articles.length ? ` (${articles.length})` : ""}`], ["info", "Verein"]];
  return (
    <Modal onClose={onClose}>
      <div className="lr-k" id="club-modal">
        <div className="lr-k-head">
          <span className="lr-k-logo"><Logo name={name} /></span>
          <div className="lr-k-title">
            <h2>{name}</h2>
            <span className="lr-k-sub">
              {club ? `${club.lg.name} · ${COUNTRY[club.sec].name}${view && view.row ? ` · Platz ${view.row.pos}` : ""}` : "Europapokal-Teilnehmer"}
              {" · Stärke "}{club ? club.s.strengths[club.i] : squadStrength(squad)}
            </span>
          </div>
          <button className={`lr-btn lr-btn-sm${fav ? " lr-btn-p" : ""}`} id="club-fav" onClick={toggleFav} title="Zu „Meine Vereine“ hinzufügen">
            {fav ? "★ Favorit" : "☆ Favorit"}
          </button>
        </div>
        <div className="lr-k-tabs">
          {tabs.map(([k, l]) => <button key={k} className="lr-k-tab" data-on={tab === k ? "1" : "0"} onClick={() => setTab(k)}>{l}</button>)}
        </div>

        {tab === "ueber" && (
          <div className="lr-k-body">
            {view && view.row ? (
              <div className="lr-k-stats">
                <div><b>{view.row.pos}.</b><span>Platz</span></div>
                <div><b>{view.row.pkt}</b><span>Punkte</span></div>
                <div><b>{view.row.sp}</b><span>Spiele</span></div>
                <div><b>{view.row.s}-{view.row.u}-{view.row.n}</b><span>S-U-N</span></div>
                <div><b>{view.row.t}:{view.row.gt}</b><span>Tore</span></div>
                <div><b>{view.row.diff > 0 ? `+${view.row.diff}` : view.row.diff}</b><span>Differenz</span></div>
              </div>
            ) : <p className="lr-hint">Dieser Verein spielt in keiner der hinterlegten Ligen mit.</p>}
            {view && view.row && <div style={{ margin: "10px 0" }}><Form form={view.row.form} /></div>}
            {club && lastPlayed && (
              <div className="lr-k-card"><small>Letztes Spiel</small>
                <button className="lr-k-match" onClick={() => openMatch({ leagueId: club.id, md: lastPlayed.md, gi: lastPlayed.gi })}>
                  <span>{lastPlayed.home ? name : club.s.teams[lastPlayed.opp]}</span><b>{lastPlayed.hg}:{lastPlayed.ag}</b><span>{lastPlayed.home ? club.s.teams[lastPlayed.opp] : name}</span>
                </button>
              </div>
            )}
            {club && next && (
              <div className="lr-k-card"><small>Nächstes Spiel · {next.md + 1}. Spieltag{next.date ? ` · ${fmtLong(next.date)}` : ""}</small>
                <button className="lr-k-match" onClick={() => openMatch({ leagueId: club.id, md: next.md, gi: next.gi })}>
                  <span>{next.home ? name : club.s.teams[next.opp]}</span><b>–:–</b><span>{next.home ? club.s.teams[next.opp] : name}</span>
                </button>
              </div>
            )}
            {view && view.scorers.length > 0 && (
              <div className="lr-k-card"><small>Torschützen der Saison</small>
                {view.scorers.slice(0, 5).map((x) => (
                  <div className="lr-k-row" key={x.name}><PlayerLink name={x.name} /><b>{x.tore}</b></div>
                ))}
              </div>
            )}
            {(info.trainer || info.stadium) && (
              <p className="lr-hint" style={{ marginTop: 10 }}>{info.trainer ? `Trainer: ${info.trainer}. ` : ""}{info.stadium ? `Stadion: ${info.stadium}.` : ""}</p>
            )}
          </div>
        )}

        {tab === "spiele" && (
          <div className="lr-k-body" id="club-games">
            {!view && <p className="lr-hint">Keine Ligaspiele vorhanden.</p>}
            {view && view.games.map((g) => (
              <button key={`${g.md}:${g.gi}`} className="lr-k-game" onClick={() => openMatch({ leagueId: club.id, md: g.md, gi: g.gi })}>
                <small>{g.md + 1}. Spieltag{g.date ? ` · ${pad2(g.date.getDate())}.${pad2(g.date.getMonth() + 1)}.` : ""}</small>
                <span className="lr-k-opp"><i>{g.home ? "H" : "A"}</i><Logo name={club.s.teams[g.opp]} />{club.s.teams[g.opp]}</span>
                <b data-r={g.res ? (g.res[0] > g.res[1] ? "s" : g.res[0] < g.res[1] ? "n" : "u") : ""}>{g.res ? `${g.res[0]}:${g.res[1]}` : "–:–"}</b>
              </button>
            ))}
          </div>
        )}

        {tab === "kader" && (
          <div className="lr-k-body" id="club-squad">
            {["TW", "ABW", "MF", "ST"].map((pos) => (byPos[pos] || []).length ? (
              <div key={pos} className="lr-k-card"><small>{POS_NAMES[pos]}</small>
                {byPos[pos].map((p) => (
                  <div className="lr-k-row" key={p.n}>
                    <span><PlayerLink name={p.n} />{!p.b ? "" : <em> Bank</em>}</span>
                    <span><span className="lr-k-g">{goalsOf(p.n) ? `${goalsOf(p.n)} Tore` : ""}</span> <b>{p.s}</b></span>
                  </div>
                ))}
              </div>
            ) : null)}
          </div>
        )}

        {tab === "news" && (
          <div className="lr-k-body">
            {!articles.length && <p className="lr-hint">Noch keine Artikel zu {name}.</p>}
            {articles.map((a) => (
              <button key={a.id} className="lr-k-art" onClick={() => openArticle(a.id)}><small>{a.date} · {a.cat}</small><b>{a.title}</b></button>
            ))}
            <button className="lr-btn lr-btn-sm lr-btn-p" id="club-new-article" onClick={() => newArticle({ team: name, cat: "Verein", section: club ? club.sec : "" })}>Artikel zu {name} schreiben</button>
          </div>
        )}

        {tab === "info" && (
          <div className="lr-k-body">
            <div className="lr-k-form">
              <KField label="Trainer" id="ci-trainer" value={info.trainer} onChange={(v) => setInfo({ ...info, trainer: v })} />
              <KField label="Stadion" id="ci-stadium" value={info.stadium} onChange={(v) => setInfo({ ...info, stadium: v })} />
              <KField label="Stadt" value={info.city} onChange={(v) => setInfo({ ...info, city: v })} />
              <KField label="Gegründet" value={info.founded} onChange={(v) => setInfo({ ...info, founded: v })} />
              <KField label="Vereinsfarben" value={info.colors} onChange={(v) => setInfo({ ...info, colors: v })} />
              <KField label="Präsident" value={info.president} onChange={(v) => setInfo({ ...info, president: v })} />
            </div>
            <label className="lr-k-field wide"><span>Notizen</span>
              <textarea className="lr-team-in" id="ci-note" rows={4} value={info.note} onChange={(e) => setInfo({ ...info, note: e.target.value })} />
            </label>
            <div className="lr-modal-foot" style={{ marginTop: 10 }}>
              <span className="lr-status">{flash}</span>
              <button className="lr-btn lr-btn-p" id="ci-save" onClick={saveInfo}>Speichern</button>
            </div>
          </div>
        )}

        <div className="lr-modal-foot" style={{ marginTop: 14 }}>
          <button className="lr-btn" onClick={onClose}>Schließen</button>
        </div>
      </div>
    </Modal>
  );
}

/* ---- Spielerseite ---- */

function PlayerModal({ data, setData, name, onClose }) {
  const { openClub, openMatch } = useContext(ClubCtx);
  const f = findPlayer(data, name);
  const saved = (data.playerInfo || {})[name] || {};
  const [info, setInfo] = useState({ number: saved.number || "", age: saved.age || "", nation: saved.nation || "", height: saved.height || "", foot: saved.foot || "", value: saved.value || "", contract: saved.contract || "", note: saved.note || "" });
  const [flash, setFlash] = useState("");
  const [to, setTo] = useState("");
  const club = f ? findClub(data, f.club) : null;
  const goals = club ? playerGoals(club.s, club.i, name) : [];
  const save = () => {
    setData((d) => ({ ...d, playerInfo: { ...(d.playerInfo || {}), [name]: { ...info } } }));
    setFlash("Gespeichert.");
    setTimeout(() => setFlash(""), 1800);
  };
  return (
    <Modal onClose={onClose}>
      <div className="lr-k" id="player-modal">
        <div className="lr-k-head">
          <span className="lr-k-logo"><Logo name={f ? f.club : ""} /></span>
          <div className="lr-k-title">
            <h2>{name}</h2>
            <span className="lr-k-sub">
              {f ? (<>{POS_NAMES[f.pl.p] || f.pl.p} · <TeamLink name={f.club} /> · Stärke {f.pl.s}{f.pl.b ? " · Bank" : " · Startelf"}</>) : "Spieler nicht in einem Kader gefunden"}
            </span>
          </div>
        </div>
        <div className="lr-k-stats">
          <div><b>{goals.length}</b><span>Tore (Liga)</span></div>
          <div><b>{info.number || "–"}</b><span>Nummer</span></div>
          <div><b>{info.age || "–"}</b><span>Alter</span></div>
          <div><b>{info.nation || "–"}</b><span>Nation</span></div>
          <div><b>{info.value || "–"}</b><span>Marktwert</span></div>
        </div>
        {goals.length > 0 && (
          <div className="lr-k-card"><small>Tore in dieser Saison</small>
            {goals.map((g, i) => (
              <button className="lr-k-game" key={i} onClick={() => club && openMatch({ leagueId: club.id, md: g.md - 1, gi: null, opp: g.opp, club: f.club })}>
                <small>{g.md}. Spieltag</small><span className="lr-k-opp"><i>{g.home ? "H" : "A"}</i><Logo name={g.opp} />{g.opp}</span><b>{g.m ? `${g.m}'` : "–"}</b>
              </button>
            ))}
          </div>
        )}
        {f && (
          <div className="lr-k-card" style={{ marginTop: 12 }}><small>Transfer</small>
            <div className="lr-k-addcard" style={{ border: 0, margin: 0, padding: 0 }}>
              <select className="lr-jump" id="pi-to" value={to} aria-label="Neuer Verein" onChange={(e) => setTo(e.target.value)}>
                <option value="">Neuer Verein …</option>
                {LEAGUE_ALL_IDS.map((id) => (data.active[id] ? (
                  <optgroup key={id} label={LEAGUE_BY_ID[id].name}>
                    {data.active[id].teams.filter((t) => t !== f.club).map((t) => <option key={t} value={t}>{t}</option>)}
                  </optgroup>
                ) : null))}
              </select>
              <button className="lr-btn lr-btn-sm" id="pi-transfer" disabled={!to || playersOf(f.squad).length <= 15} onClick={() => { setData((d) => transferPlayer(d, name, to)); setTo(""); setFlash(`Wechsel zu ${to} vollzogen.`); }}>Wechsel vollziehen</button>
            </div>
            {playersOf(f.squad).length <= 15 && <span className="lr-hint">{f.club} hat nur noch 15 Spieler und kann niemanden abgeben.</span>}
          </div>
        )}
        <h3 className="lr-sec-h" style={{ marginTop: 14 }}>Angaben</h3>
        <div className="lr-k-form">
          <KField label="Rückennummer" value={info.number} onChange={(v) => setInfo({ ...info, number: v })} />
          <KField label="Alter" id="pi-age" value={info.age} onChange={(v) => setInfo({ ...info, age: v })} />
          <KField label="Nationalität" value={info.nation} onChange={(v) => setInfo({ ...info, nation: v })} />
          <KField label="Größe" value={info.height} onChange={(v) => setInfo({ ...info, height: v })} />
          <KField label="Starker Fuß" value={info.foot} onChange={(v) => setInfo({ ...info, foot: v })} />
          <KField label="Marktwert" value={info.value} onChange={(v) => setInfo({ ...info, value: v })} />
          <KField label="Vertrag bis" value={info.contract} onChange={(v) => setInfo({ ...info, contract: v })} />
        </div>
        <label className="lr-k-field wide"><span>Notizen</span>
          <textarea className="lr-team-in" id="pi-note" rows={3} value={info.note} onChange={(e) => setInfo({ ...info, note: e.target.value })} />
        </label>
        <div className="lr-modal-foot">
          <span className="lr-status">{flash}</span>
          {f && <button className="lr-btn" onClick={() => openClub(f.club)}>Zum Verein</button>}
          <button className="lr-btn lr-btn-p" id="pi-save" onClick={save}>Speichern</button>
          <button className="lr-btn" onClick={onClose}>Schließen</button>
        </div>
      </div>
    </Modal>
  );
}

/* ---- Spielbericht ---- */

const CARD_LABEL = { gelb: "Gelbe Karte", rot: "Rote Karte", gelbrot: "Gelb-Rot" };

function MatchModal({ data, setData, at, onClose }) {
  const { openClub, openPlayer, show3d, newArticle } = useContext(ClubCtx);
  const s = data.active[at.leagueId];
  const fx = useMemo(() => makeFixtures(s.teams.length, s.seed), [s]);
  let { md, gi } = at;
  if (gi == null) {
    const ci = s.teams.indexOf(at.club);
    const oi = s.teams.indexOf(at.opp);
    gi = (fx[md] || []).findIndex(([h, a]) => (h === ci && a === oi) || (h === oi && a === ci));
  }
  const pair = fx[md] && fx[md][gi];
  const [tab, setTab] = useState("ticker");
  const key = pair ? matchKey(at.leagueId, s.label, md, gi) : "";
  const saved = (data.matchInfo || {})[key] || {};
  const [info, setInfo] = useState({ stadium: saved.stadium || "", att: saved.att || "", ref: saved.ref || "", report: saved.report || "" });
  const [events, setEvents] = useState(Array.isArray(saved.events) ? saved.events : []);
  const [card, setCard] = useState({ t: "h", p: "", m: "", k: "gelb" });
  const [flash, setFlash] = useState("");
  if (!pair) return (<Modal onClose={onClose}><div className="lr-k"><h2>Spielbericht</h2><p className="lr-hint">Dieses Spiel wurde nicht gefunden.</p><div className="lr-modal-foot"><button className="lr-btn" onClick={onClose}>Schließen</button></div></div></Modal>);
  const [h, a] = pair;
  const home = s.teams[h];
  const away = s.teams[a];
  const resRaw = s.results[`${md}:${gi}`];
  const res = parsedResult(s.results, md, gi);
  const dates = matchdayDates(s.start, fx.length);
  const rows = computeTable(s.teams, fx, s.results);
  const rowOf = (i) => rows.find((r) => r.idx === i);
  const stadiumDefault = ((data.clubInfo || {})[home] || {}).stadium || "";
  const sqH = s.squads[h];
  const sqA = s.squads[a];
  const goals = res ? fillGoals(resRaw.sc, sqH, sqA, res[0], res[1]) : [];
  const timeline = [
    ...goals.map((g) => ({ kind: "tor", t: g.t, p: g.p, m: g.m || 0 })),
    ...events.map((e, i) => ({ kind: e.k, t: e.t, p: e.p, m: Number(e.m) || 0, i })),
  ].sort((x, y) => x.m - y.m);
  let sh = 0;
  let sa = 0;
  timeline.forEach((e) => { if (e.kind === "tor") { if (e.t === "h") sh++; else sa++; e.score = `${sh}:${sa}`; } });

  const persist = (patch) => setData((d) => ({ ...d, matchInfo: { ...(d.matchInfo || {}), [key]: { ...((d.matchInfo || {})[key] || {}), ...patch } } }));
  const saveInfo = () => { persist({ ...info }); setFlash("Gespeichert."); setTimeout(() => setFlash(""), 1800); };
  const addCard = () => {
    if (!card.p) return;
    const next = [...events, { ...card, m: Number(card.m) || 0 }];
    setEvents(next); persist({ events: next }); setCard({ ...card, p: "", m: "" });
  };
  const delCard = (i) => { const next = events.filter((_, k) => k !== i); setEvents(next); persist({ events: next }); };

  const reportText = () => {
    const list = goals.map((g) => `${g.m || "?"}. Minute: ${g.p || "Tor"} (${g.t === "h" ? home : away})`).join("\n");
    const sc = res ? `${res[0]}:${res[1]}` : "–:–";
    return `${home} gegen ${away} endete ${sc}.${list ? `\n\nTore:\n${list}` : ""}${info.att ? `\n\nZuschauer: ${info.att}.` : ""}`;
  };
  const publish = () => {
    const title = res ? resultHeadline({ h: home, a: away, hg: res[0], ag: res[1] }) : `${home} – ${away}`;
    newArticle({ title, teaser: `${s.label}, ${md + 1}. Spieltag ${LEAGUE_BY_ID[at.leagueId].name}: ${home} ${res ? `${res[0]}:${res[1]}` : "–:–"} ${away}`, body: info.report.trim() || reportText(), cat: "Spielbericht", team: home, section: sectionOfLeagueId(at.leagueId), date: todayISO() });
  };
  const open3d = () => {
    const side = (i) => ({ name: s.teams[i], strength: s.strengths[i], squad: s.squads[i] });
    const drawShare = DRAW_SHARE[data.drawBias || 0] != null ? DRAW_SHARE[data.drawBias || 0] : 0;
    const surprise = data.surpriseBias == null ? 1 : Number(data.surpriseBias);
    show3d({
      home: side(h), away: side(a), hg: resRaw ? resRaw.h : "", ag: resRaw ? resRaw.a : "", sc: resRaw ? resRaw.sc : null,
      sim: () => simulateMatch(s.strengths[h], s.strengths[a], false, drawShare, surprise, formationTilt(s.squads[h].f), formationTilt(s.squads[a].f)),
      onTake: (hg, ag, sc) => setData((d) => ({ ...d, active: { ...d.active, [at.leagueId]: { ...d.active[at.leagueId], results: { ...d.active[at.leagueId].results, [`${md}:${gi}`]: { h: String(hg), a: String(ag), sc } } } } })),
    });
  };

  // Aufstellung als Grafik
  const lay = { h: m3Layout(sqH, home), a: m3Layout(sqA, away) };
  const colors = { h: "#e4514a", a: "#4c8bf5" };
  const pt = (team, sl) => (team === "h" ? { x: 4 + sl.u * 68, y: 32 + sl.v * 26 } : { x: 96 - sl.u * 68, y: 32 - sl.v * 26 });

  const cmp = (label, x, y, higherBetter = true) => {
    const tot = (Number(x) || 0) + (Number(y) || 0) || 1;
    const wx = Math.round(((Number(x) || 0) / tot) * 100);
    return (
      <div className="lr-k-cmp" key={label}>
        <b className={higherBetter ? ((x >= y) ? "lead" : "") : ((x <= y) ? "lead" : "")}>{x}</b>
        <div className="lr-k-bar"><i style={{ width: `${wx}%` }} /></div>
        <b className={higherBetter ? ((y >= x) ? "lead" : "") : ((y <= x) ? "lead" : "")}>{y}</b>
        <small>{label}</small>
      </div>
    );
  };
  const rh = rowOf(h);
  const ra = rowOf(a);
  const other = fx.flatMap((round, mi) => round.map(([x, y], g2) => ({ mi, g2, x, y }))).find((q) => !(q.mi === md && q.g2 === gi) && ((q.x === h && q.y === a) || (q.x === a && q.y === h)));
  const otherRes = other ? parsedResult(s.results, other.mi, other.g2) : null;

  const tabs = [["ticker", "Ticker"], ["lineup", "Aufstellung"], ["cmp", "Vergleich"], ["info", "Spielinfos"]];
  return (
    <Modal onClose={onClose}>
      <div className="lr-k" id="match-modal">
        <p className="lr-k-sub" style={{ margin: 0 }}>{LEAGUE_BY_ID[at.leagueId].name} · {s.label} · {md + 1}. Spieltag{dates[md] ? ` · ${fmtLong(dates[md])}` : ""}</p>
        <div className="lr-m3-hud" id="mr-hud">
          <span className="lr-m3-t r"><span><TeamLink name={home} /></span><Logo name={home} /></span>
          <b className="lr-m3-sc" id="mr-score">{res ? `${res[0]}:${res[1]}` : "–:–"}</b>
          <span className="lr-m3-t"><Logo name={away} /><span><TeamLink name={away} /></span></span>
        </div>
        <div className="lr-k-tabs">
          {tabs.map(([k, l]) => <button key={k} className="lr-k-tab" data-on={tab === k ? "1" : "0"} onClick={() => setTab(k)}>{l}</button>)}
        </div>

        {tab === "ticker" && (
          <div className="lr-k-body" id="mr-ticker">
            {!res && <p className="lr-hint">Das Spiel wurde noch nicht gespielt. Das Ergebnis lässt sich auf dem Spieltag eintragen, simulieren oder direkt in der 3D-Ansicht übernehmen.</p>}
            {res && <div className="lr-k-ev"><small>0'</small><span>Anpfiff</span></div>}
            {timeline.map((e, i) => (
              <div className="lr-k-ev" key={i} data-k={e.kind}>
                <small>{e.m ? `${e.m}'` : "–"}</small>
                <span>
                  <i className="lr-k-ic" data-k={e.kind} />
                  {e.kind === "tor" ? <>Tor {e.t === "h" ? home : away}{e.p ? <> — <PlayerLink name={e.p} /></> : ""} <b>{e.score}</b></> : <>{CARD_LABEL[e.kind]} {e.t === "h" ? home : away} — {e.p ? <PlayerLink name={e.p} /> : ""}</>}
                </span>
                {e.kind !== "tor" && <button className="lr-k-x" title="Eintrag entfernen" onClick={() => delCard(e.i)}>×</button>}
              </div>
            ))}
            {res && <div className="lr-k-ev"><small>90'</small><span>Abpfiff — {home} {res[0]}:{res[1]} {away}</span></div>}
            {res && (
              <div className="lr-k-addcard">
                <b>Karte eintragen</b>
                <select className="lr-jump" value={card.t} aria-label="Mannschaft" onChange={(e) => setCard({ ...card, t: e.target.value, p: "" })}>
                  <option value="h">{home}</option><option value="a">{away}</option>
                </select>
                <select className="lr-jump" id="mr-card-p" value={card.p} aria-label="Spieler" onChange={(e) => setCard({ ...card, p: e.target.value })}>
                  <option value="">Spieler wählen</option>
                  {playersOf(card.t === "h" ? sqH : sqA).map((p) => <option key={p.n} value={p.n}>{p.n}</option>)}
                </select>
                <input className="lr-team-in" style={{ width: 70 }} placeholder="Minute" value={card.m} aria-label="Minute" onChange={(e) => setCard({ ...card, m: e.target.value.replace(/[^0-9]/g, "").slice(0, 2) })} />
                <select className="lr-jump" id="mr-card-k" value={card.k} aria-label="Art" onChange={(e) => setCard({ ...card, k: e.target.value })}>
                  <option value="gelb">Gelb</option><option value="gelbrot">Gelb-Rot</option><option value="rot">Rot</option>
                </select>
                <button className="lr-btn lr-btn-sm" id="mr-card-add" onClick={addCard} disabled={!card.p}>Hinzufügen</button>
              </div>
            )}
          </div>
        )}

        {tab === "lineup" && (
          <div className="lr-k-body" id="mr-lineup">
            <svg viewBox="0 0 100 64" className="lr-k-pitch" role="img" aria-label="Aufstellung">
              <rect x="0" y="0" width="100" height="64" fill="#2f7a3f" />
              <g stroke="rgba(255,255,255,.7)" strokeWidth=".35" fill="none">
                <rect x="1" y="1" width="98" height="62" /><line x1="50" y1="1" x2="50" y2="63" /><circle cx="50" cy="32" r="7" />
                <rect x="1" y="14" width="13" height="36" /><rect x="86" y="14" width="13" height="36" />
              </g>
              {["h", "a"].map((team) => lay[team].map((sl, n) => {
                const p = pt(team, sl);
                return (
                  <g key={team + n}>
                    <circle cx={p.x} cy={p.y} r="1.7" fill={colors[team]} stroke="#fff" strokeWidth=".4" />
                    <text x={p.x} y={p.y + 4.2} fontSize="2" textAnchor="middle" fill="#fff" stroke="rgba(0,0,0,.55)" strokeWidth=".5" paintOrder="stroke">{lastName(sl.name)}</text>
                  </g>
                );
              }))}
            </svg>
            <div className="lr-k-two">
              {[["h", home, sqH], ["a", away, sqA]].map(([t, nm, sq]) => (
                <div className="lr-k-card" key={t}><small>{nm} · {sq.f}</small>
                  {playersOf(sq).filter((p) => !p.b).map((p) => <div className="lr-k-row" key={p.n}><PlayerLink name={p.n} /><b>{p.s}</b></div>)}
                  <small style={{ marginTop: 8 }}>Bank</small>
                  {playersOf(sq).filter((p) => p.b).map((p) => <div className="lr-k-row" key={p.n}><PlayerLink name={p.n} /><b>{p.s}</b></div>)}
                </div>
              ))}
            </div>
          </div>
        )}

        {tab === "cmp" && (
          <div className="lr-k-body" id="mr-cmp">
            {rh && ra && (
              <>
                {cmp("Tabellenplatz", rh.pos, ra.pos, false)}
                {cmp("Punkte", rh.pkt, ra.pkt)}
                {cmp("Tore", rh.t, ra.t)}
                {cmp("Gegentore", rh.gt, ra.gt, false)}
                {cmp("Stärke", s.strengths[h], s.strengths[a])}
                <div className="lr-k-cmp"><span><Form form={rh.form} /></span><span /><span><Form form={ra.form} /></span><small>Form</small></div>
              </>
            )}
            <div className="lr-k-card"><small>Direkter Vergleich in dieser Saison</small>
              {other ? (
                <div className="lr-k-row"><span>{other.mi + 1}. Spieltag: {s.teams[other.x]} – {s.teams[other.y]}</span><b>{otherRes ? `${otherRes[0]}:${otherRes[1]}` : "–:–"}</b></div>
              ) : <span className="lr-hint">Kein weiteres Duell.</span>}
            </div>
          </div>
        )}

        {tab === "info" && (
          <div className="lr-k-body" id="mr-info">
            <div className="lr-k-form">
              <KField label="Stadion" id="mr-stadium" value={info.stadium} placeholder={stadiumDefault} onChange={(v) => setInfo({ ...info, stadium: v })} />
              <KField label="Zuschauer" id="mr-att" value={info.att} onChange={(v) => setInfo({ ...info, att: v })} />
              <KField label="Schiedsrichter" id="mr-ref" value={info.ref} onChange={(v) => setInfo({ ...info, ref: v })} />
            </div>
            <label className="lr-k-field wide"><span>Spielbericht</span>
              <textarea className="lr-team-in" id="mr-report" rows={7} value={info.report} placeholder="Eigenen Spielbericht schreiben – leer gelassen entsteht beim Veröffentlichen ein kurzer Bericht aus den Toren."
                onChange={(e) => setInfo({ ...info, report: e.target.value })} />
            </label>
            <div className="lr-modal-foot" style={{ marginTop: 10 }}>
              <span className="lr-status">{flash}</span>
              <button className="lr-btn" id="mr-publish" onClick={() => { saveInfo(); publish(); }}>Als Artikel veröffentlichen</button>
              <button className="lr-btn lr-btn-p" id="mr-save" onClick={saveInfo}>Speichern</button>
            </div>
          </div>
        )}

        <div className="lr-modal-foot" style={{ marginTop: 14 }}>
          <button className="lr-btn" id="mr-3d" onClick={open3d}>3D ansehen</button>
          <button className="lr-btn" onClick={onClose}>Schließen</button>
        </div>
      </div>
    </Modal>
  );
}

/* ---- Artikel ---- */

function ArticleModal({ data, setData, id, onClose, onEdit }) {
  const { openClub } = useContext(ClubCtx);
  const a = (data.news || []).find((x) => x.id === id);
  const [ask, setAsk] = useState(false);
  if (!a) return null;
  const del = () => { setData((d) => ({ ...d, news: d.news.filter((x) => x.id !== id) })); onClose(); };
  const togglePin = () => setData((d) => ({ ...d, news: d.news.map((x) => (x.id === id ? { ...x, pinned: !x.pinned } : x)) }));
  return (
    <Modal onClose={onClose}>
      <div className="lr-k lr-k-article" id="article-modal">
        <small className="lr-k-tag">{a.cat}{a.section ? ` · ${COUNTRY[a.section].name}` : ""}</small>
        <h2>{a.title}</h2>
        {a.teaser && <p className="lr-k-teaser">{a.teaser}</p>}
        {a.img && <img className="lr-k-img" src={a.img} alt="" />}
        <div className="lr-k-text">{a.body.split(/\n{2,}/).map((p, i) => <p key={i}>{p.split("\n").map((l, j) => <React.Fragment key={j}>{j ? <br /> : null}{l}</React.Fragment>)}</p>)}</div>
        <p className="lr-hint">{a.date}{a.team ? <> · <TeamLink name={a.team} /></> : ""}</p>
        <div className="lr-modal-foot">
          {ask ? (
            <>
              <span className="lr-status">Artikel wirklich löschen?</span>
              <button className="lr-btn" onClick={() => setAsk(false)}>Nein</button>
              <button className="lr-btn lr-btn-p" id="article-del-ok" onClick={del}>Ja, löschen</button>
            </>
          ) : (
            <>
              <button className="lr-btn" id="article-del" onClick={() => setAsk(true)}>Löschen</button>
              <button className="lr-btn" onClick={togglePin}>{a.pinned ? "Nicht mehr anpinnen" : "Anpinnen"}</button>
              <button className="lr-btn lr-btn-p" id="article-edit" onClick={() => onEdit(a)}>Bearbeiten</button>
              <button className="lr-btn" onClick={onClose}>Schließen</button>
            </>
          )}
        </div>
      </div>
    </Modal>
  );
}

function ArticleEditor({ data, draft, onSave, onClose }) {
  const [a, setA] = useState({ title: "", teaser: "", body: "", cat: "Sonstiges", section: "", team: "", date: todayISO(), pinned: false, img: "", ...draft });
  const [err, setErr] = useState("");
  const teams = useMemo(() => LEAGUE_ALL_IDS.flatMap((id) => (data.active[id] ? data.active[id].teams : [])), [data]);
  const pick = async (e) => {
    const f = e.target.files && e.target.files[0];
    if (!f) return;
    try { setA((x) => ({ ...x, img: "" })); const url = await logoFromFile(f, 560, "image/jpeg", 0.72); setA((x) => ({ ...x, img: url })); }
    catch (x) { setErr("Das Bild konnte nicht gelesen werden."); }
  };
  const ok = a.title.trim() && (a.body.trim() || a.teaser.trim());
  return (
    <Modal onClose={onClose}>
      <div className="lr-k" id="article-editor">
        <h2>{a.id ? "Artikel bearbeiten" : "Neuer Artikel"}</h2>
        <KField label="Überschrift" id="ae-title" wide value={a.title} onChange={(v) => setA({ ...a, title: v })} />
        <KField label="Unterzeile" id="ae-teaser" wide value={a.teaser} onChange={(v) => setA({ ...a, teaser: v })} />
        <label className="lr-k-field wide"><span>Text</span>
          <textarea className="lr-team-in" id="ae-body" rows={9} value={a.body} onChange={(e) => setA({ ...a, body: e.target.value })} placeholder="Leerzeile = neuer Absatz" />
        </label>
        <div className="lr-k-form">
          <label className="lr-k-field"><span>Rubrik</span>
            <select className="lr-team-in" id="ae-cat" value={a.cat} onChange={(e) => setA({ ...a, cat: e.target.value })}>{NEWS_CATS.map((c) => <option key={c}>{c}</option>)}</select>
          </label>
          <label className="lr-k-field"><span>Abschnitt</span>
            <select className="lr-team-in" id="ae-section" value={a.section} onChange={(e) => setA({ ...a, section: e.target.value })}>
              <option value="">alle</option>{SECTION_KEYS.map((k) => <option key={k} value={k}>{COUNTRY[k].name}</option>)}
            </select>
          </label>
          <label className="lr-k-field"><span>Verein</span>
            <input className="lr-team-in" id="ae-team" list="ae-teams" value={a.team} onChange={(e) => setA({ ...a, team: e.target.value })} placeholder="optional" />
            <datalist id="ae-teams">{teams.map((t) => <option key={t} value={t} />)}</datalist>
          </label>
          <KField label="Datum" type="date" id="ae-date" value={a.date} onChange={(v) => setA({ ...a, date: v })} />
        </div>
        <div className="lr-k-img-row">
          <label className="lr-btn lr-btn-sm" style={{ cursor: "pointer" }}>Bild wählen<input type="file" accept="image/*" hidden onChange={pick} /></label>
          {a.img && <><img className="lr-k-thumb" src={a.img} alt="" /><button className="lr-btn lr-btn-sm" onClick={() => setA({ ...a, img: "" })}>Bild entfernen</button></>}
          <label className="lr-prog" style={{ display: "flex", gap: 6, alignItems: "center", marginLeft: "auto" }}><input type="checkbox" checked={a.pinned} onChange={(e) => setA({ ...a, pinned: e.target.checked })} />Anpinnen</label>
        </div>
        {err && <p className="lr-hint" style={{ color: "#f0867f" }}>{err}</p>}
        <div className="lr-modal-foot">
          <button className="lr-btn" onClick={onClose}>Abbrechen</button>
          <button className="lr-btn lr-btn-p" id="ae-save" disabled={!ok} onClick={() => onSave({ ...a, title: a.title.trim(), id: a.id || newId("a") })}>Speichern</button>
        </div>
      </div>
    </Modal>
  );
}

/* ---- Nachrichten-Tab ---- */

function NewsTab({ data, section, onNew }) {
  const { openArticle, openClub, openMatch, favorites } = useContext(ClubCtx);
  const [cat, setCat] = useState("Alle");
  const list = (data.news || [])
    .filter((a) => (!a.section || a.section === section) && (cat === "Alle" || a.cat === cat))
    .sort((x, y) => (Number(y.pinned) - Number(x.pinned)) || (y.date > x.date ? 1 : y.date < x.date ? -1 : 0));
  const results = useMemo(() => autoNews(data, section), [data, section]);
  const top = COUNTRY[section].top;
  const topSeason = data.active[top];
  const topRows = useMemo(() => (topSeason ? computeTable(topSeason.teams, makeFixtures(topSeason.teams.length, topSeason.seed), topSeason.results).slice(0, 5) : []), [topSeason]);
  const scorers = useMemo(() => (topSeason ? scorerList(seasonGames(topSeason, makeFixtures(topSeason.teams.length, topSeason.seed)), squadIndex([topSeason])).slice(0, 5) : []), [topSeason]);
  const favInfo = favorites.map((name) => {
    const c = findClub(data, name);
    if (!c) return { name, text: "" };
    const g = clubGames(c.s, c.i);
    const last = [...g].reverse().find((x) => x.res);
    const next = g.find((x) => !x.res);
    return { name, c, last, next };
  });
  return (
    <div className="lr-wrap" id="news-tab">
      <div className="lr-k-newsgrid">
        <section>
          <div className="lr-k-newshead">
            <h2 className="lr-sec-h" style={{ margin: 0 }}>Nachrichten</h2>
            <div className="lr-spacer" />
            <button className="lr-btn lr-btn-sm lr-btn-p" id="news-new" onClick={() => onNew({ section })}>Neuer Artikel</button>
          </div>
          <div className="lr-k-chips" role="group" aria-label="Rubrik">
            {["Alle", ...NEWS_CATS].map((c) => <button key={c} className="lr-k-chip" data-on={cat === c ? "1" : "0"} onClick={() => setCat(c)}>{c}</button>)}
          </div>
          {!list.length && <p className="lr-empty">Noch keine Artikel. Mit „Neuer Artikel“ schreibst du den ersten – oder veröffentliche einen Spielbericht direkt aus einem Spiel.</p>}
          {results.length > 0 && cat === "Alle" && (
            <div className="lr-k-card" id="news-auto"><small>Aus den Ergebnissen</small>
              {[...results].sort((x, y) => Number(y.sens) - Number(x.sens) || Math.abs(y.hg - y.ag) - Math.abs(x.hg - x.ag)).slice(0, 6).map((r) => (
                <button key={`${r.leagueId}${r.gi}`} className="lr-k-art" onClick={() => openMatch({ leagueId: r.leagueId, md: r.md, gi: r.gi })}>
                  <small>{r.lg} · {r.md + 1}. Spieltag{r.sens ? " · Sensation" : ""}</small><b>{resultHeadline(r)}</b>
                </button>
              ))}
            </div>
          )}
          {list.map((a) => (
            <article className="lr-k-news" key={a.id} data-pin={a.pinned ? "1" : "0"} onClick={() => openArticle(a.id)} role="button" tabIndex={0}
              onKeyDown={(e) => { if (e.key === "Enter") openArticle(a.id); }}>
              {a.img ? <img src={a.img} alt="" /> : <div className="lr-k-noimg">{a.team ? <Logo name={a.team} /> : null}</div>}
              <div>
                <small className="lr-k-tag">{a.pinned ? "📌 " : ""}{a.cat}{a.section ? ` · ${COUNTRY[a.section].name}` : ""}</small>
                <h3>{a.title}</h3>
                {a.teaser && <p>{a.teaser}</p>}
                <small>{a.date}{a.team ? ` · ${a.team}` : ""}</small>
              </div>
            </article>
          ))}
        </section>
        <aside>
          <div className="lr-k-card" id="news-favs"><small>Meine Vereine</small>
            {!favInfo.length && <span className="lr-hint">Auf einer Vereinsseite mit „☆ Favorit“ hinzufügen.</span>}
            {favInfo.map((f) => (
              <div key={f.name} className="lr-k-fav">
                <button className="lr-k-link" onClick={() => openClub(f.name)}><Logo name={f.name} />{f.name}</button>
                {f.c && f.last && <button className="lr-k-mini" onClick={() => openMatch({ leagueId: f.c.id, md: f.last.md, gi: f.last.gi })}>{f.last.home ? `${f.name} ${f.last.hg}:${f.last.ag} ${f.c.s.teams[f.last.opp]}` : `${f.c.s.teams[f.last.opp]} ${f.last.hg}:${f.last.ag} ${f.name}`}</button>}
                {f.c && f.next && <small>Nächstes: {f.next.home ? `${f.name} – ${f.c.s.teams[f.next.opp]}` : `${f.c.s.teams[f.next.opp]} – ${f.name}`}</small>}
              </div>
            ))}
          </div>
          <div className="lr-k-card" id="news-results"><small>Ergebnisse des letzten Spieltags</small>
            {!results.length && <span className="lr-hint">Noch keine Ergebnisse.</span>}
            {results.slice(0, 14).map((r) => (
              <button key={`${r.leagueId}${r.gi}`} className="lr-k-res" onClick={() => openMatch({ leagueId: r.leagueId, md: r.md, gi: r.gi })} title={resultHeadline(r)}>
                <span>{r.h}</span><b>{r.hg}:{r.ag}</b><span>{r.a}</span>
              </button>
            ))}
          </div>
          {results.filter((r) => r.sens).length > 0 && (
            <div className="lr-k-card"><small>Sensationen</small>
              {results.filter((r) => r.sens).slice(0, 4).map((r) => <div key={`${r.leagueId}${r.gi}`} className="lr-k-row"><span>{resultHeadline(r)}</span></div>)}
            </div>
          )}
          {topRows.length > 0 && (
            <div className="lr-k-card"><small>{COUNTRY[section].topName}: Spitze</small>
              {topRows.map((r) => <div key={r.name} className="lr-k-row"><span>{r.pos}. <TeamLink name={r.name} /></span><b>{r.pkt}</b></div>)}
            </div>
          )}
          {scorers.length > 0 && (
            <div className="lr-k-card"><small>Torjäger</small>
              {scorers.map((x) => <div key={x.name} className="lr-k-row"><span><PlayerLink name={x.name} /> <em>{x.verein}</em></span><b>{x.tore}</b></div>)}
            </div>
          )}
        </aside>
      </div>
    </div>
  );
}

/* ---- Vereine-Tab ---- */

function ClubsTab({ data, section }) {
  const { openClub, favorites } = useContext(ClubCtx);
  const [q, setQ] = useState("");
  const all = useMemo(() => clubsOfSection(data, section), [data, section]);
  const match = (c) => !q.trim() || c.name.toLowerCase().indexOf(q.trim().toLowerCase()) >= 0;
  const favs = all.filter((c) => favorites.indexOf(c.name) >= 0 && match(c));
  return (
    <div className="lr-wrap" id="clubs-tab">
      <div className="lr-k-newshead">
        <h2 className="lr-sec-h" style={{ margin: 0 }}>Vereine</h2>
        <div className="lr-spacer" />
        <input className="lr-team-in" id="clubs-q" style={{ maxWidth: 240 }} placeholder="Verein suchen" value={q} onChange={(e) => setQ(e.target.value)} aria-label="Verein suchen" />
      </div>
      {favs.length > 0 && (
        <>
          <h3 className="lr-k-lh">★ Meine Vereine</h3>
          <div className="lr-k-clubs">{favs.map((c) => <ClubTile key={`f${c.name}`} c={c} onOpen={openClub} />)}</div>
        </>
      )}
      {COUNTRY[section].leagues.map((lg) => {
        const rows = all.filter((c) => c.id === lg.id && match(c)).sort((x, y) => x.pos - y.pos);
        if (!rows.length) return null;
        return (
          <React.Fragment key={lg.id}>
            <h3 className="lr-k-lh" style={{ color: lg.accent }}>{lg.name}</h3>
            <div className="lr-k-clubs">{rows.map((c) => <ClubTile key={c.name} c={c} onOpen={openClub} />)}</div>
          </React.Fragment>
        );
      })}
    </div>
  );
}

function ClubTile({ c, onOpen }) {
  return (
    <button className="lr-k-tile" onClick={() => onOpen(c.name)}>
      <Logo name={c.name} /><span>{c.name}</span><small>{c.pos}. · {c.strength}</small>
    </button>
  );
}

/* ---- Suche ---- */

function SearchBox({ data }) {
  const { openClub, openPlayer } = useContext(ClubCtx);
  const [q, setQ] = useState("");
  const res = useMemo(() => searchAll(data, q), [data, q]);
  const any = res.clubs.length + res.players.length > 0;
  const go = (fn, v) => { setQ(""); fn(v); };
  return (
    <div className="lr-k-search">
      <input id="search-q" className="lr-team-in" placeholder="Verein oder Spieler suchen" aria-label="Suche" value={q} onChange={(e) => setQ(e.target.value)} />
      {q.trim().length >= 2 && (
        <div className="lr-k-dd" id="search-res">
          {!any && <span className="lr-hint" style={{ padding: 8 }}>Nichts gefunden.</span>}
          {res.clubs.map((c) => <button key={`c${c.name}`} onClick={() => go(openClub, c.name)}><Logo name={c.name} />{c.name}<small>{c.lg}</small></button>)}
          {res.players.map((p) => <button key={`p${p.name}`} onClick={() => go(openPlayer, p.name)}><b>{p.name}</b><small>{p.club} · {POS_NAMES[p.pos] || p.pos}</small></button>)}
        </div>
      )}
    </div>
  );
}

/* ---------------- 3D-Ansicht ---------------- */

/** Spielfeld in Metern: x längs (Heim links, Gast rechts), y quer, z nach oben. Ein Spiel dauert in der 3D-Ansicht drei Minuten. */
const M3_SECONDS = 180;
const M3_HALF_L = 52.5;
const M3_HALF_W = 34;

const m3Clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
const m3Ease = (s) => s * s * (3 - 2 * s);
const m3Lerp = (a, b, s) => a + (b - a) * s;

/** Aufstellung eines Kaders: Torwart plus Feldspieler mit Grundposition (u = 0 eigenes Tor … 1 gegnerisches Tor, v = quer). */
function m3Layout(squad, teamName) {
  const list = playersOf(squad);
  const name = (i) => (i != null && list[i] ? String(list[i].n) : "Spieler");
  const rows = squad ? pitchRows(squad) : { gk: null, linien: [[null, null, null, null], [null, null, null, null], [null, null]] };
  const slots = [{ idx: rows.gk, name: rows.gk != null ? name(rows.gk) : `Torwart ${teamName}`, gk: true, u: 0.04, v: 0, line: -1 }];
  const R = rows.linien.length;
  rows.linien.forEach((row, r) => {
    const u = R === 1 ? 0.4 : 0.2 + (0.62 - 0.2) * (r / (R - 1));
    const n = row.length;
    row.forEach((pi, k) => {
      const span = n >= 4 ? 0.9 : n === 3 ? 0.7 : 0.4;
      slots.push({ idx: pi, name: name(pi), gk: false, u, v: n === 1 ? 0 : -span + (2 * span * k) / (n - 1), line: r, last: r === R - 1 });
    });
  });
  return slots;
}

const m3World = (team, u, v) => ({ x: team === "h" ? -50 + 100 * u : 50 - 100 * u, y: (team === "h" ? 1 : -1) * v * 30 });

/** Freie Position eines Spielers (ohne Ballkontakt), abhängig vom Ballfokus und davon, wer den Ball hat. */
function m3Free(team, slot, F, poss, clock, phase) {
  const bu = team === "h" ? (F.x + 50) / 100 : (50 - F.x) / 100;
  const hasBall = poss === team;
  let u;
  let v = slot.v;
  if (slot.gk) {
    u = 0.035 + 0.07 * m3Clamp(bu, 0, 1);
    const w = m3World(team, u, 0);
    return { x: w.x, y: m3Clamp(F.y * 0.16, -5, 5) };
  }
  const du = (bu - 0.45) * 0.42 + (hasBall ? 0.05 : -0.03);
  u = m3Clamp(slot.u + du * (0.55 + 0.7 * slot.u), 0.07, 0.96);
  v = v * (hasBall ? 1.12 : 0.86);
  const w = m3World(team, u, v);
  w.y += F.y * 0.1;
  w.x += Math.sin(clock * 0.9 + phase) * 0.7;
  w.y += Math.cos(clock * 0.7 + phase * 1.3) * 0.7;
  return w;
}

/**
 * Spielverlauf als Zeitleiste in Spielminuten: Ballwege (Pässe, Schüsse), Tore zu den echten Minuten, Torjubel, Anstoß.
 * Alles hängt nur von Ergebnis, Torschützen und Seed ab – die Ansicht lässt sich also beliebig vor- und zurückspulen.
 */
function m3Build(spec) {
  const rnd = mulberry32(spec.seed);
  const lay = { h: spec.H, a: spec.A };
  const segs = [];
  const goals = [];
  let t = 0;
  let ball = { x: 0, y: 0 };
  let poss = rnd() < 0.5 ? "h" : "a";
  const other = (tm) => (tm === "h" ? "a" : "h");
  const goalX = (tm) => (tm === "h" ? M3_HALF_L : -M3_HALF_L);
  const strength = { h: Math.max(1, Number(spec.sh) || 50), a: Math.max(1, Number(spec.sa) || 50) };

  const push = (s) => {
    const seg = { type: "pass", peak: 0, from: null, to: null, focus: null, ...s, t0: t, t1: t + s.dur };
    segs.push(seg);
    t = seg.t1;
    ball = { x: seg.b.x, y: seg.b.y };
    return seg;
  };
  const nearestSlot = (tm, pt, notIdx, allowGk) => {
    let best = -1;
    let bd = 1e9;
    lay[tm].forEach((sl, i) => {
      if ((sl.gk && !allowGk) || i === notIdx) return;
      const p = m3Free(tm, sl, pt, tm, 0, i);
      const d = (p.x - pt.x) ** 2 + (p.y - pt.y) ** 2;
      if (d < bd) { bd = d; best = i; }
    });
    return best;
  };
  const slotByName = (tm, nm) => lay[tm].findIndex((sl) => nm && sl.name === nm);

  /** Ein Angriff mit Passfolge; `end`: goal | save | wide | lost | none. */
  const attack = (tm, dur, end, shooterName) => {
    const opp = other(tm);
    const n = m3Clamp(Math.round(dur / 0.4), 2, 6);
    const startU = m3Clamp((tm === "h" ? (ball.x + 50) / 100 : (50 - ball.x) / 100), 0.05, 0.7);
    const shootU = 0.78 + rnd() * 0.1;
    let holder = nearestSlot(tm, ball, -1, true);
    let shooter = end === "goal" || end === "save" || end === "wide" ? slotByName(tm, shooterName) : -1;
    if (shooter < 0 && (end === "goal" || end === "save" || end === "wide")) {
      const front = lay[tm].map((sl, i) => (sl.last ? i : -1)).filter((i) => i >= 0);
      const mid = lay[tm].map((sl, i) => (!sl.gk && !sl.last && sl.line >= 1 ? i : -1)).filter((i) => i >= 0);
      shooter = rnd() < 0.7 && front.length ? front[Math.floor(rnd() * front.length)] : mid.length ? mid[Math.floor(rnd() * mid.length)] : front[0];
    }
    const shotTime = end === "none" || end === "lost" ? 0 : 0.32;
    const dt = Math.max(0.15, (dur - shotTime) / n);
    for (let i = 1; i <= n; i++) {
      const last = i === n;
      const u = m3Lerp(startU, shootU, i / n) + (rnd() - 0.5) * 0.06;
      const v = last && shooter >= 0 ? (rnd() - 0.5) * 0.8 : (rnd() - 0.5) * 1.5;
      const pt = m3World(tm, m3Clamp(u, 0.05, 0.93), v);
      const to = last && shooter >= 0 ? shooter : nearestSlot(tm, pt, holder, false);
      const dist = Math.hypot(pt.x - ball.x, pt.y - ball.y);
      push({ team: tm, type: dist < 6 ? "carry" : "pass", dur: dt, a: { ...ball }, b: pt, peak: dist > 28 ? 2 + rnd() * 3 : 0, from: holder, to });
      holder = to;
    }
    const gx = goalX(tm);
    const sign = tm === "h" ? 1 : -1;
    const here = { ...ball };
    if (end === "goal") {
      const gy = (rnd() < 0.5 ? -1 : 1) * (1.4 + rnd() * 2);
      push({ team: tm, type: "shot", dur: shotTime, a: here, b: { x: gx + sign * 1.1, y: gy }, bz: 0.4 + rnd() * 1.5, from: holder, to: null, keeper: { y: -Math.sign(gy) * (1.5 + rnd() * 1.5), dive: true } });
    } else if (end === "save") {
      const gy = (rnd() - 0.5) * 6;
      push({ team: tm, type: "shot", dur: shotTime, a: here, b: { x: gx - sign * 0.6, y: gy }, bz: 0.3 + rnd() * 1.2, from: holder, to: null, keeper: { y: gy, dive: true } });
      const dfs = lay[opp].map((sl, i) => (!sl.gk && sl.line === 0 ? i : -1)).filter((i) => i >= 0);
      const dfi = dfs.length ? dfs[Math.floor(rnd() * dfs.length)] : 1;
      const dp = m3Free(opp, lay[opp][dfi], here, opp, 0, dfi);
      push({ team: opp, type: "pass", dur: 0.45, a: { ...ball }, b: { x: m3Clamp(dp.x, -48, 48), y: dp.y }, peak: 0.5, from: 0, to: dfi, focusKeep: true });
      poss = opp;
    } else if (end === "wide") {
      const gy = (rnd() < 0.5 ? -1 : 1) * (4.3 + rnd() * 3);
      push({ team: tm, type: "shot", dur: shotTime, a: here, b: { x: gx + sign * 2.5, y: gy }, bz: rnd() < 0.5 ? 3.4 : 0.6, from: holder, to: null, keeper: { y: gy * 0.3, dive: false } });
      push({ team: opp, type: "hold", dur: 0.25, a: { ...ball }, b: { ...ball }, from: null, to: null });
      const kick = m3World(opp, 0.06, 0);
      push({ team: opp, type: "pass", dur: 0.01, a: kick, b: kick, from: 0, to: 0 });
      poss = opp;
    } else if (end === "lost") {
      const ix = nearestSlot(opp, ball, -1, false);
      const ip = m3Free(opp, lay[opp][ix], ball, opp, 0, ix);
      push({ team: opp, type: "pass", dur: 0.35, a: { ...ball }, b: { x: ip.x, y: ip.y }, peak: 0, from: null, to: ix });
      poss = opp;
    } else {
      poss = tm;
    }
  };

  const celebrate = (g, tm, shooter) => {
    const opp = other(tm);
    const sign = tm === "h" ? 1 : -1;
    const corner = { x: sign * 44, y: (rnd() < 0.5 ? -1 : 1) * 28 };
    push({ team: tm, type: "celebrate", dur: 0.9, a: { ...ball }, b: { ...ball }, bz: 0.4, focus: { x: 0, y: 0 }, from: shooter, to: null, corner, goal: g });
    push({ team: opp, type: "hold", dur: 0.2, a: { x: 0, y: 0 }, b: { x: 0, y: 0 }, from: null, to: null, focus: { x: 0, y: 0 } });
    poss = opp;
  };

  // Tore: Minuten in Reihenfolge bringen und mindestens drei Minuten Abstand halten.
  const gl = [...spec.goals].sort((x, y) => (x.m || 0) - (y.m || 0)).map((g) => ({ ...g }));
  let prev = 1.5;
  gl.forEach((g) => {
    g.m = m3Clamp(g.m || 1 + Math.floor(rnd() * 88), 2.6, 89);
    if (g.m < prev + 3) g.m = Math.min(89.5, prev + 3);
    prev = g.m;
  });

  push({ team: poss, type: "hold", dur: 0.35, a: { x: 0, y: 0 }, b: { x: 0, y: 0 }, from: null, to: null, focus: { x: 0, y: 0 } });

  const share = (tm) => strength[tm] / (strength.h + strength.a);
  const filler = (limit) => {
    while (limit - t > 0.9) {
      const tm = poss;
      const room = limit - t;
      const dur = Math.min(room, 1.5 + rnd() * 1.1 + (share(tm) - 0.5) * 1.5);
      const pShot = m3Clamp(0.2 + (share(tm) - 0.5) * 1.3, 0.08, 0.5);
      const roll = rnd();
      const end = dur < 1.2 ? "lost" : roll < pShot * 0.6 ? "save" : roll < pShot ? "wide" : "lost";
      attack(tm, dur, end);
    }
    if (limit - t > 0.02) push({ team: poss, type: "hold", dur: limit - t, a: { ...ball }, b: { ...ball }, from: null, to: null });
  };

  gl.forEach((g) => {
    const start = Math.max(t, g.m - 2.0);
    filler(start);
    const dur = g.m - t;
    if (dur < 0.6) { // zu wenig Platz: Tor ohne Vorspiel
      t = Math.max(0, g.m - 0.6);
    }
    const tm = g.t;
    // Ball zum angreifenden Team holen
    if (poss !== tm) poss = tm;
    attack(tm, Math.max(0.6, g.m - t), "goal", g.p);
    const shot = segs[segs.length - 1];
    goals.push({ ...g, at: shot.t1, shooter: shot.from });
    celebrate(g, tm, shot.from);
  });
  filler(Math.max(90, t + 0.5));
  return { segs, goals, total: t };
}

/** Ballposition (mit Höhe), Ballfokus und aktives Segment zur Spielminute `tm`. */
function m3At(tl, tm, hint) {
  const segs = tl.segs;
  let i = hint && segs[hint.i] && segs[hint.i].t0 <= tm ? hint.i : 0;
  while (i < segs.length - 1 && segs[i].t1 <= tm) i++;
  const s = segs[i];
  const k = s.t1 > s.t0 ? m3Clamp((tm - s.t0) / (s.t1 - s.t0), 0, 1) : 1;
  let z = 0.11;
  let x = m3Lerp(s.a.x, s.b.x, k);
  let y = m3Lerp(s.a.y, s.b.y, k);
  if (s.type === "shot") z = 0.11 + m3Lerp(0.2, s.bz || 0.5, k) + Math.sin(k * Math.PI) * 0.4;
  else if (s.peak) z = 0.11 + s.peak * 4 * k * (1 - k);
  else if (s.type === "pass") z = 0.11 + 0.25 * Math.sin(k * Math.PI);
  if (s.type === "celebrate") z = 0.4 + (s.bz || 0);
  return { i, seg: s, k, ball: { x, y, z }, focus: s.focus || { x, y } };
}

/** Geglätteter Ballfokus der letzten Spielsekunden: die Teams folgen dem Ball weich. */
function m3Focus(tl, tm, hint) {
  let fx = 0;
  let fy = 0;
  const N = 5;
  let h = hint;
  for (let j = 0; j < N; j++) {
    const at = m3At(tl, Math.max(0, tm - j * 0.12), j === 0 ? h : null);
    if (j === 0) h = at;
    fx += at.focus.x;
    fy += at.focus.y;
  }
  return { x: fx / N, y: fy / N };
}

/** Alle Spielerpositionen zur Spielminute `tm` (Heim: 0–10, Gast: 11–21). */
function m3Players(tl, spec, tm, clock) {
  const cur = m3At(tl, tm, null);
  const F = m3Focus(tl, tm, cur);
  const s = cur.seg;
  const poss = s.team;
  const out = [];
  const ballXY = cur.ball;
  ["h", "a"].forEach((team) => {
    const lay = team === "h" ? spec.H : spec.A;
    // die beiden ballnächsten Feldspieler des Teams ohne Ball rücken auf den Ball zu
    const dist = lay.map((sl, i) => {
      const p = m3Free(team, sl, F, poss, clock, i);
      return { i, p, d: Math.hypot(p.x - ballXY.x, p.y - ballXY.y) };
    });
    const press = team !== poss ? [...dist].filter((q) => !lay[q.i].gk).sort((a, b) => a.d - b.d).slice(0, 2).map((q) => q.i) : [];
    lay.forEach((sl, i) => {
      let p = { ...dist[i].p };
      let dive = 0;
      if (press.indexOf(i) >= 0 && dist[i].d < 22) {
        const w = 0.55 * (1 - dist[i].d / 22);
        p = { x: m3Lerp(p.x, ballXY.x, w), y: m3Lerp(p.y, ballXY.y, w) };
      }
      // Ballbesitzer und Passempfänger werden zum Ball gezogen
      if (s.team === team || s.type === "celebrate") {
        if (s.from === i) {
          const wFrom = s.type === "celebrate" ? 0 : 1 - m3Ease(m3Clamp(cur.k * 3, 0, 1));
          if (s.type === "carry") p = { x: ballXY.x - (s.b.x - s.a.x > 0 ? 0.4 : -0.4), y: ballXY.y };
          else if (wFrom > 0) p = { x: m3Lerp(p.x, s.a.x, wFrom), y: m3Lerp(p.y, s.a.y, wFrom) };
        }
        if (s.to === i && s.type !== "hold") {
          const w = m3Ease(m3Clamp((cur.k - 0.25) / 0.75, 0, 1));
          p = { x: m3Lerp(p.x, s.b.x, w), y: m3Lerp(p.y, s.b.y, w) };
        }
      }
      if (s.type === "celebrate" && s.from === i && team === s.team) {
        const w = m3Ease(cur.k);
        p = { x: m3Lerp(s.a.x, s.corner.x, w), y: m3Lerp(s.a.y, s.corner.y, w) };
      }
      if (s.type === "hold" && s.from == null && s.focus && s.t1 - s.t0 < 0.4 && s.team === team && sl.last && sl.v < 0.3 && sl.v > -0.3) {
        p = { x: team === "h" ? -0.8 : 0.8, y: 0 }; // Anstoßspieler
      }
      if (sl.gk) {
        if (s.type === "shot" && s.keeper && s.team !== team) {
          const w = m3Ease(m3Clamp(cur.k * 1.4, 0, 1));
          const gx = team === "h" ? -M3_HALF_L + 1.2 : M3_HALF_L - 1.2;
          p = { x: m3Lerp(p.x, gx, w * 0.6), y: m3Lerp(p.y, s.keeper.y, w) };
          if (s.keeper.dive) dive = Math.sign(s.keeper.y - dist[i].p.y || 1) * w;
        }
        if (s.type === "pass" && s.focusKeep && s.from === 0 && s.team === team) {
          p = { x: m3Lerp(s.a.x, p.x, m3Ease(cur.k)), y: m3Lerp(s.a.y, p.y, m3Ease(cur.k)) };
        }
      }
      out.push({ team, i, slot: sl, x: p.x, y: p.y, dive });
    });
  });
  return { players: out, ball: cur.ball, seg: s, k: cur.k };
}

/* ---- Kamera und Zeichnen ---- */

function m3Project(cam, W, H, P) {
  const vx = P.x - cam.pos[0];
  const vy = P.y - cam.pos[1];
  const vz = (P.z || 0) - cam.pos[2];
  const xc = vx * cam.r[0] + vy * cam.r[1] + vz * cam.r[2];
  const yc = vx * cam.u[0] + vy * cam.u[1] + vz * cam.u[2];
  const zc = vx * cam.f[0] + vy * cam.f[1] + vz * cam.f[2];
  if (zc < 0.5) return null;
  const F = (H / 2) / Math.tan(cam.fov / 2);
  return { x: W / 2 + (xc / zc) * F, y: H / 2 - (yc / zc) * F, d: zc, s: F / zc };
}

function m3Camera(yaw, pitch, dist, target, fov) {
  const cp = Math.cos(pitch);
  const pos = [target[0] + dist * cp * Math.cos(yaw), target[1] + dist * cp * Math.sin(yaw), target[2] + dist * Math.sin(pitch)];
  let f = [target[0] - pos[0], target[1] - pos[1], target[2] - pos[2]];
  const fl = Math.hypot(...f);
  f = f.map((v) => v / fl);
  let r = [f[1] * 1 - f[2] * 0, f[2] * 0 - f[0] * 1, 0]; // f × (0,0,1)
  const rl = Math.hypot(...r) || 1;
  r = r.map((v) => v / rl);
  const u = [r[1] * f[2] - r[2] * f[1], r[2] * f[0] - r[0] * f[2], r[0] * f[1] - r[1] * f[0]];
  return { pos, f, r, u, fov };
}

const M3_VIEWS = {
  tv: { name: "TV-Kamera", yaw: -Math.PI / 2, pitch: 0.46, dist: 58, follow: true },
  oben: { name: "Vogelperspektive", yaw: -Math.PI / 2, pitch: 1.3, dist: 105, follow: true },
  tor: { name: "Hinter dem Tor", yaw: Math.PI, pitch: 0.24, dist: 48, follow: true },
  stadion: { name: "Stadion", yaw: -2.2, pitch: 0.36, dist: 120, follow: false },
};

function m3Draw(ctx, W, H, st) {
  const { tl, spec, tm, clock, cam: camState, colors } = st;
  const pl = m3Players(tl, spec, tm, clock);
  const ballXY = pl.ball;
  const target = [camState.follow ? m3Clamp(ballXY.x * 0.75, -34, 34) : 0, camState.follow ? ballXY.y * 0.25 : 0, 0];
  const cam = m3Camera(camState.yaw, camState.pitch, camState.dist, target, 0.8);
  const P = (x, y, z) => m3Project(cam, W, H, { x, y, z });

  // Himmel und Umgebung
  const sky = ctx.createLinearGradient(0, 0, 0, H);
  sky.addColorStop(0, "#0d1a2a");
  sky.addColorStop(0.5, "#23384c");
  sky.addColorStop(1, "#1b3a26");
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, W, H);
  const poly = (pts, fill, stroke, lw) => {
    const q = pts.map((p) => P(p[0], p[1], p[2] || 0));
    if (q.some((p) => !p)) return;
    ctx.beginPath();
    q.forEach((p, i) => (i ? ctx.lineTo(p.x, p.y) : ctx.moveTo(p.x, p.y)));
    ctx.closePath();
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw || 1; ctx.stroke(); }
  };
  const line = (pts, color, lw) => {
    ctx.beginPath();
    let started = false;
    pts.forEach((p) => {
      const q = P(p[0], p[1], p[2] || 0);
      if (!q) { started = false; return; }
      if (!started) { ctx.moveTo(q.x, q.y); started = true; } else ctx.lineTo(q.x, q.y);
    });
    ctx.strokeStyle = color;
    ctx.lineWidth = lw || 1;
    ctx.stroke();
  };

  // Umfeld
  poly([[-120, -90], [120, -90], [120, 90], [-120, 90]], "#17301f");
  // Tribünen als ansteigende Wände mit Zuschauerpunkten
  const stands = [
    [[-M3_HALF_L - 10, -M3_HALF_W - 9], [M3_HALF_L + 10, -M3_HALF_W - 9]],
    [[-M3_HALF_L - 10, M3_HALF_W + 9], [M3_HALF_L + 10, M3_HALF_W + 9]],
    [[-M3_HALF_L - 12, -M3_HALF_W - 9], [-M3_HALF_L - 12, M3_HALF_W + 9]],
    [[M3_HALF_L + 12, -M3_HALF_W - 9], [M3_HALF_L + 12, M3_HALF_W + 9]],
  ];
  const outer = [];
  stands.forEach((s, si) => {
    const dx = si < 2 ? 0 : (si === 2 ? -1 : 1) * 14;
    const dy = si >= 2 ? 0 : (si === 0 ? -1 : 1) * 14;
    outer.push({ si, a: s[0], b: s[1], dx, dy });
  });
  outer.sort((p, q) => {
    const pc = P((p.a[0] + p.b[0]) / 2, (p.a[1] + p.b[1]) / 2, 3);
    const qc = P((q.a[0] + q.b[0]) / 2, (q.a[1] + q.b[1]) / 2, 3);
    return (qc ? qc.d : 0) - (pc ? pc.d : 0);
  });
  outer.forEach((o) => {
    poly([[o.a[0], o.a[1], 0], [o.b[0], o.b[1], 0], [o.b[0] + o.dx, o.b[1] + o.dy, 11], [o.a[0] + o.dx, o.a[1] + o.dy, 11]], "#222c34", "rgba(255,255,255,0.05)", 1);
    const rnd = mulberry32(o.si * 977 + 13);
    const len = Math.hypot(o.b[0] - o.a[0], o.b[1] - o.a[1]);
    const count = Math.round(len * 1.6);
    for (let n = 0; n < count; n++) {
      const t1 = rnd();
      const t2 = 0.08 + rnd() * 0.88;
      const x = m3Lerp(o.a[0], o.b[0], t1) + o.dx * t2;
      const y = m3Lerp(o.a[1], o.b[1], t1) + o.dy * t2;
      const q = P(x, y, 11 * t2 + 0.6);
      if (!q) continue;
      const pulse = Math.sin(clock * 3 + n) * 0.5 + 0.5;
      ctx.fillStyle = `hsl(${(n * 47) % 360},40%,${38 + pulse * (pl.seg.type === "celebrate" ? 30 : 8)}%)`;
      ctx.fillRect(q.x - q.s * 0.25, q.y - q.s * 0.35, Math.max(1.4, q.s * 0.5), Math.max(1.4, q.s * 0.7));
    }
  });
  // Rasen
  poly([[-M3_HALF_L - 8, -M3_HALF_W - 8], [M3_HALF_L + 8, -M3_HALF_W - 8], [M3_HALF_L + 8, M3_HALF_W + 8], [-M3_HALF_L - 8, M3_HALF_W + 8]], "#2c6e3a");
  const stripes = 14;
  for (let k = 0; k < stripes; k++) {
    const x0 = -M3_HALF_L + (k * 2 * M3_HALF_L) / stripes;
    const x1 = -M3_HALF_L + ((k + 1) * 2 * M3_HALF_L) / stripes;
    poly([[x0, -M3_HALF_W], [x1, -M3_HALF_W], [x1, M3_HALF_W], [x0, M3_HALF_W]], k % 2 ? "#3b8a49" : "#347d42");
  }
  // Linien
  const white = "rgba(255,255,255,0.92)";
  const lw = Math.max(1, (P(0, 0, 0) ? P(0, 0, 0).s : 8) * 0.14);
  line([[-M3_HALF_L, -M3_HALF_W], [M3_HALF_L, -M3_HALF_W], [M3_HALF_L, M3_HALF_W], [-M3_HALF_L, M3_HALF_W], [-M3_HALF_L, -M3_HALF_W]], white, lw);
  line([[0, -M3_HALF_W], [0, M3_HALF_W]], white, lw);
  const circle = (cx, cy, r, a0, a1, color) => {
    const pts = [];
    for (let k = 0; k <= 36; k++) { const a = a0 + ((a1 - a0) * k) / 36; pts.push([cx + r * Math.cos(a), cy + r * Math.sin(a)]); }
    line(pts, color, lw);
  };
  circle(0, 0, 9.15, 0, Math.PI * 2, white);
  [-1, 1].forEach((sd) => {
    const gx = sd * M3_HALF_L;
    line([[gx, -20.15], [gx - sd * 16.5, -20.15], [gx - sd * 16.5, 20.15], [gx, 20.15]], white, lw);
    line([[gx, -9.16], [gx - sd * 5.5, -9.16], [gx - sd * 5.5, 9.16], [gx, 9.16]], white, lw);
    const sp = gx - sd * 11;
    circle(sp, 0, 0.25, 0, Math.PI * 2, white);
    circle(sp, 0, 9.15, sd > 0 ? Math.PI - 0.93 : -0.93, sd > 0 ? Math.PI + 0.93 : 0.93, white);
  });

  // Objekte nach Tiefe sortiert zeichnen (weit hinten zuerst)
  const objs = [];
  const goalFrame = (sd) => {
    const gx = sd * M3_HALF_L;
    const back = gx + sd * 2.2;
    const c = P(gx + sd, 0, 1.2);
    objs.push({
      d: c ? c.d : 1e9,
      draw: () => {
        const netC = "rgba(255,255,255,0.28)";
        for (let yy = -3.66; yy <= 3.67; yy += 0.61) line([[gx, yy, 0], [back, yy, 0], [back, yy, 2.44], [gx, yy, 2.44]], netC, 1);
        for (let zz = 0.4; zz <= 2.44; zz += 0.41) line([[gx, -3.66, zz], [back, -3.66, zz], [back, 3.66, zz], [gx, 3.66, zz]], netC, 1);
        line([[gx, -3.66, 0], [gx, -3.66, 2.44], [gx, 3.66, 2.44], [gx, 3.66, 0]], "#f4f4f0", Math.max(2, lw * 1.6));
      },
    });
  };
  goalFrame(-1);
  goalFrame(1);

  // Ball
  const bp = P(ballXY.x, ballXY.y, ballXY.z);
  const bsh = P(ballXY.x, ballXY.y, 0);
  if (bp && bsh) {
    objs.push({
      d: bp.d - 0.2,
      draw: () => {
        ctx.fillStyle = "rgba(0,0,0,0.35)";
        ctx.beginPath(); ctx.ellipse(bsh.x, bsh.y, bsh.s * 0.22, bsh.s * 0.09, 0, 0, Math.PI * 2); ctx.fill();
        const r = Math.max(2.4, bp.s * 0.2);
        ctx.fillStyle = "#fff";
        ctx.beginPath(); ctx.arc(bp.x, bp.y, r, 0, Math.PI * 2); ctx.fill();
        ctx.strokeStyle = "#222"; ctx.lineWidth = Math.max(1, r * 0.22);
        ctx.beginPath(); ctx.arc(bp.x, bp.y, r, 0, Math.PI * 2); ctx.stroke();
        ctx.fillStyle = "#222";
        ctx.beginPath(); ctx.arc(bp.x - r * 0.15, bp.y - r * 0.1, r * 0.34, 0, Math.PI * 2); ctx.fill();
      },
    });
  }

  // Spieler
  const prevPl = m3Players(tl, spec, Math.max(0, tm - 0.06), clock - 0.1).players;
  pl.players.forEach((p, n) => {
    const pr = prevPl[n];
    const foot = P(p.x, p.y, 0);
    if (!foot) return;
    const dxv = p.x - pr.x;
    const dyv = p.y - pr.y;
    const sp = Math.hypot(dxv, dyv);
    objs.push({
      d: foot.d,
      draw: () => {
        const sc = foot.s;
        const col = p.slot.gk ? colors[p.team].gk : colors[p.team].shirt;
        ctx.fillStyle = "rgba(0,0,0,0.33)";
        ctx.beginPath(); ctx.ellipse(foot.x, foot.y, sc * 0.5, sc * 0.2, 0, 0, Math.PI * 2); ctx.fill();
        const phase = clock * 9 + n;
        const swing = Math.min(1, sp * 14) * 0.45;
        const ux = sp > 0.0005 ? dxv / sp : 0;
        const uy = sp > 0.0005 ? dyv / sp : 0;
        const leg = (sgn) => {
          const o = Math.sin(phase * (sgn > 0 ? 1 : 1) + (sgn > 0 ? 0 : Math.PI)) * swing;
          const f = P(p.x + ux * o, p.y + uy * o + sgn * 0.12, Math.max(0, Math.cos(phase + (sgn > 0 ? 0 : Math.PI)) * 0.12 * Math.min(1, sp * 14)));
          const hip = P(p.x, p.y + sgn * 0.1, 0.92);
          if (!f || !hip) return;
          ctx.strokeStyle = colors[p.team].shorts;
          ctx.lineWidth = Math.max(1.4, sc * 0.17);
          ctx.beginPath(); ctx.moveTo(hip.x, hip.y); ctx.lineTo(f.x, f.y); ctx.stroke();
          ctx.strokeStyle = colors[p.team].socks;
          ctx.lineWidth = Math.max(1.2, sc * 0.13);
          ctx.beginPath(); ctx.moveTo(m3Lerp(hip.x, f.x, 0.55), m3Lerp(hip.y, f.y, 0.55)); ctx.lineTo(f.x, f.y); ctx.stroke();
        };
        let hipP;
        let shP;
        let headP;
        if (p.dive) {
          hipP = P(p.x, p.y, 0.45);
          shP = P(p.x, p.y + p.dive * 1.2, 0.9);
          headP = P(p.x, p.y + p.dive * 1.55, 1.0);
        } else {
          leg(1); leg(-1);
          hipP = P(p.x, p.y, 0.95);
          shP = P(p.x, p.y, 1.5);
          headP = P(p.x, p.y, 1.72);
        }
        if (!hipP || !shP || !headP) return;
        ctx.strokeStyle = col;
        ctx.lineCap = "round";
        ctx.lineWidth = Math.max(2, sc * 0.46);
        ctx.beginPath(); ctx.moveTo(hipP.x, hipP.y); ctx.lineTo(shP.x, shP.y); ctx.stroke();
        // Arme
        const armSw = Math.min(1, sp * 14) * 0.4;
        [-1, 1].forEach((sgn) => {
          const hand = p.dive ? P(p.x, p.y + p.dive * 2.2, 1.0) : P(p.x + ux * Math.sin(phase + (sgn > 0 ? Math.PI : 0)) * armSw, p.y + sgn * 0.42, 1.0);
          if (!hand) return;
          ctx.strokeStyle = col; ctx.lineWidth = Math.max(1.2, sc * 0.13);
          ctx.beginPath(); ctx.moveTo(shP.x, shP.y); ctx.lineTo(hand.x, hand.y); ctx.stroke();
        });
        ctx.lineCap = "butt";
        ctx.fillStyle = "#e9c9a6";
        ctx.beginPath(); ctx.arc(headP.x, headP.y, Math.max(2, sc * 0.14), 0, Math.PI * 2); ctx.fill();
      },
    });
  });
  objs.sort((a, b) => b.d - a.d);
  objs.forEach((o) => o.draw());

  // Name des Ballführenden
  const cs = pl.seg;
  const holder = cs.type === "shot" || cs.type === "celebrate" ? cs.from : cs.k > 0.5 && cs.to != null ? cs.to : cs.from;
  const hp = holder != null ? pl.players.find((q) => q.team === cs.team && q.i === holder) : null;
  if (hp && cs.type !== "hold") {
    const q = P(hp.x, hp.y, 2.3);
    if (q) {
      ctx.font = `600 ${Math.max(11, Math.min(15, q.s * 0.5))}px sans-serif`;
      const label = hp.slot.name;
      const w = ctx.measureText(label).width + 12;
      ctx.fillStyle = "rgba(10,16,12,0.72)";
      ctx.fillRect(q.x - w / 2, q.y - 12, w, 18);
      ctx.fillStyle = "#fff";
      ctx.textAlign = "center";
      ctx.fillText(label, q.x, q.y + 1);
      ctx.textAlign = "left";
    }
  }
}

/** Dominante Trikotfarbe aus dem Vereinslogo (Fallback: aus dem Namen). */
function m3Hash(name) {
  let h = 7;
  for (let i = 0; i < name.length; i++) h = (h * 31 + name.charCodeAt(i)) >>> 0;
  return h;
}

function m3KitFrom(hue, light) {
  return {
    shirt: `hsl(${hue},68%,${light}%)`,
    shorts: light > 60 ? "#223" : "#f3f3f3",
    socks: `hsl(${hue},68%,${Math.max(25, light - 12)}%)`,
    gk: "#e8c32a",
  };
}

function m3Kits(homeName, awayName, colorOf) {
  const hh = colorOf(homeName);
  const ah = colorOf(awayName);
  const hue1 = hh ? hh.hue : m3Hash(homeName) % 360;
  const hue2 = ah ? ah.hue : m3Hash(awayName) % 360;
  const l1 = hh ? hh.light : 48;
  const l2 = ah ? ah.light : 48;
  const dh = (x, y) => Math.min(Math.abs(x - y), 360 - Math.abs(x - y));
  const kitH = m3KitFrom(hue1, l1);
  let kitA = m3KitFrom(hue2, l2);
  const grau = (c) => c && c.sat < 25;
  let hueA = hue2;
  if (dh(hue1, hue2) < 40 || (grau(hh) && grau(ah) && Math.abs(l1 - l2) < 12)) {
    kitA = { shirt: l1 > 60 ? "#1a1f2b" : "#f2f2ee", shorts: l1 > 60 ? "#f2f2ee" : "#1a1f2b", socks: l1 > 60 ? "#1a1f2b" : "#f2f2ee" };
    hueA = -999;
  }
  const keeper = [[52, "#e8c32a"], [185, "#3fc1c9"], [290, "#c86bd8"], [100, "#8fd14f"]];
  const ok = (hue, t) => hue === -999 || dh(hue, t) > 55;
  const pick = (hue) => (keeper.find(([th]) => ok(hue1, th) && ok(hue, th)) || keeper[1])[1];
  kitH.gk = pick(hueA);
  kitA.gk = keeper.map((k) => k[1]).find((c) => c !== kitH.gk && ok(hue1, keeper.find((k) => k[1] === c)[0]) && ok(hueA, keeper.find((k) => k[1] === c)[0])) || "#3fc1c9";
  return { h: kitH, a: kitA };
}

function m3LogoColor(src) {
  return new Promise((resolve) => {
    if (!src) { resolve(null); return; }
    const img = new Image();
    img.onload = () => {
      try {
        const c = document.createElement("canvas");
        c.width = 24; c.height = 24;
        const x = c.getContext("2d");
        x.drawImage(img, 0, 0, 24, 24);
        const d = x.getImageData(0, 0, 24, 24).data;
        const bins = new Array(12).fill(0);
        const bl = new Array(12).fill(0);
        const bs = new Array(12).fill(0);
        let grey = 0;
        let greyL = 0;
        for (let i = 0; i < d.length; i += 4) {
          const a = d[i + 3] / 255;
          if (a < 0.5) continue;
          const r = d[i] / 255, g = d[i + 1] / 255, b = d[i + 2] / 255;
          const mx = Math.max(r, g, b), mn = Math.min(r, g, b);
          const l = (mx + mn) / 2;
          const sat = mx === mn ? 0 : (mx - mn) / (1 - Math.abs(2 * l - 1));
          if (sat < 0.3 || l < 0.12 || l > 0.9) { grey++; greyL += l; continue; }
          let h;
          if (mx === r) h = ((g - b) / (mx - mn)) % 6;
          else if (mx === g) h = (b - r) / (mx - mn) + 2;
          else h = (r - g) / (mx - mn) + 4;
          h = (h * 60 + 360) % 360;
          const k = Math.floor(h / 30);
          bins[k] += sat; bl[k] += l * sat; bs[k] += sat * sat;
        }
        let best = 0;
        bins.forEach((v, k) => { if (v > bins[best]) best = k; });
        if (bins[best] < 6) resolve({ hue: 0, sat: 5, light: grey ? Math.round((greyL / grey) * 100) : 50 });
        else resolve({ hue: best * 30 + 15, sat: 70, light: m3Clamp(Math.round((bl[best] / bins[best]) * 100), 32, 56) });
      } catch (e) { resolve(null); }
    };
    img.onerror = () => resolve(null);
    img.src = src;
  });
}

/**
 * 3D-Ansicht eines Spiels. Mit Ergebnis (`hg`/`ag` gesetzt) wird die Partie nachgespielt – Tore fallen in den
 * eingetragenen Minuten, mit den eingetragenen Torschützen. Ohne Ergebnis wird eine Partie ausgewürfelt; sie lässt sich
 * danach per Knopf übernehmen (`onTake`).
 */
function Match3D({ spec, onClose }) {
  const logos = useContext(LogoCtx);
  const canvasRef = useRef(null);
  const wrapRef = useRef(null);
  const stateRef = useRef({ elapsed: 0, running: false, last: 0, speed: 1 });
  const [, bump] = useState(0);
  const [view, setView] = useState("tv");
  const [speed, setSpeed] = useState(1);
  const [running, setRunning] = useState(false);
  const [colors, setColors] = useState(() => m3Kits(spec.home.name, spec.away.name, () => null));
  const camRef = useRef({ ...M3_VIEWS.tv });

  // Ergebnis festlegen (bei offenem Spiel auswürfeln)
  const game = useMemo(() => {
    let hg = spec.hg;
    let ag = spec.ag;
    const open = hg === "" || hg == null || ag === "" || ag == null;
    if (open) [hg, ag] = spec.sim();
    hg = Number(hg); ag = Number(ag);
    let sc = Array.isArray(spec.sc) && spec.sc.length ? fillGoals(spec.sc, spec.home.squad, spec.away.squad, hg, ag) : null;
    if (!sc) sc = liveGoals(makeGoals(spec.home.squad, spec.away.squad, hg, ag), hg, ag);
    sc = sc.map((g) => ({ ...g, m: g.m > 0 ? g.m : 1 + Math.floor(Math.random() * 90) })).sort((x, y) => x.m - y.m);
    return { open, hg, ag, sc };
  }, [spec]);

  const data = useMemo(() => {
    const H = m3Layout(spec.home.squad, spec.home.name);
    const A = m3Layout(spec.away.squad, spec.away.name);
    const sp = { H, A, goals: game.sc, sh: spec.home.strength, sa: spec.away.strength, seed: m3Hash(`${spec.home.name}|${spec.away.name}|${game.hg}:${game.ag}`) ^ (game.open ? Math.floor(Math.random() * 1e9) : 0) };
    return { spec: sp, tl: m3Build(sp) };
  }, [spec, game]);

  useEffect(() => {
    let alive = true;
    Promise.all([m3LogoColor(logos[spec.home.name]), m3LogoColor(logos[spec.away.name])]).then(([a, b]) => {
      if (!alive || (!a && !b)) return;
      setColors(m3Kits(spec.home.name, spec.away.name, (nm) => (nm === spec.home.name ? a : b)));
    });
    return () => { alive = false; };
  }, [spec, logos]);

  const total = Math.max(90, data.tl.total);
  const clockMin = (s) => Math.min(total, (s.elapsed / M3_SECONDS) * 90);

  // Zeichenschleife
  useEffect(() => {
    let raf = 0;
    let alive = true;
    const frame = (now) => {
      if (!alive) return;
      const s = stateRef.current;
      if (s.running) {
        const dt = s.last ? (now - s.last) / 1000 : 0;
        s.elapsed = Math.min((total / 90) * M3_SECONDS, s.elapsed + dt * s.speed);
        if (s.elapsed >= (total / 90) * M3_SECONDS) { s.running = false; setRunning(false); }
      }
      s.last = now;
      const cv = canvasRef.current;
      const wrap = wrapRef.current;
      if (cv && wrap) {
        const dpr = Math.min(2, window.devicePixelRatio || 1);
        const w = wrap.clientWidth;
        const h = Math.round(w * 0.56);
        if (cv.width !== Math.round(w * dpr) || cv.height !== Math.round(h * dpr)) { cv.width = Math.round(w * dpr); cv.height = Math.round(h * dpr); cv.style.height = `${h}px`; }
        const ctx = cv.getContext("2d");
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        try {
          m3Draw(ctx, w, h, { tl: data.tl, spec: data.spec, tm: clockMin(s), clock: now / 1000, cam: camRef.current, colors });
        } catch (e) { /* ein Bild auslassen */ }
        s.frame = (s.frame || 0) + 1;
        if (s.frame % 6 === 0) bump((n) => n + 1);
      }
      raf = requestAnimationFrame(frame);
    };
    raf = requestAnimationFrame(frame);
    return () => { alive = false; cancelAnimationFrame(raf); };
  }, [data, colors, total]);

  // Maus / Touch: Kamera drehen, Mausrad: zoomen
  useEffect(() => {
    const cv = canvasRef.current;
    if (!cv) return undefined;
    let drag = null;
    const down = (e) => { drag = { x: e.clientX, y: e.clientY }; cv.setPointerCapture && cv.setPointerCapture(e.pointerId); };
    const move = (e) => {
      if (!drag) return;
      const cam = camRef.current;
      cam.yaw -= (e.clientX - drag.x) * 0.006;
      cam.pitch = m3Clamp(cam.pitch + (e.clientY - drag.y) * 0.005, 0.1, 1.45);
      drag = { x: e.clientX, y: e.clientY };
      setView("frei");
    };
    const up = () => { drag = null; };
    const wheel = (e) => {
      e.preventDefault();
      const cam = camRef.current;
      cam.dist = m3Clamp(cam.dist * (e.deltaY > 0 ? 1.08 : 0.92), 25, 170);
    };
    cv.addEventListener("pointerdown", down);
    cv.addEventListener("pointermove", move);
    cv.addEventListener("pointerup", up);
    cv.addEventListener("pointercancel", up);
    cv.addEventListener("wheel", wheel, { passive: false });
    return () => {
      cv.removeEventListener("pointerdown", down);
      cv.removeEventListener("pointermove", move);
      cv.removeEventListener("pointerup", up);
      cv.removeEventListener("pointercancel", up);
      cv.removeEventListener("wheel", wheel);
    };
  }, []);

  const s = stateRef.current;
  s.speed = speed;
  const minute = clockMin(s);
  const done = s.elapsed >= (total / 90) * M3_SECONDS - 0.001;
  const goalsNow = data.tl.goals.filter((g) => g.at <= minute);
  const sh = goalsNow.filter((g) => g.t === "h").length;
  const sa = goalsNow.filter((g) => g.t === "a").length;
  const lastGoal = data.tl.goals.filter((g) => g.at <= minute && minute - g.at < 2.6).slice(-1)[0];

  const toggle = () => {
    if (done) s.elapsed = 0;
    s.running = !s.running;
    s.last = 0;
    setRunning(s.running);
  };
  const seek = (m) => { s.elapsed = (Math.max(0, m) / 90) * M3_SECONDS; s.last = 0; bump((n) => n + 1); };
  const pickView = (k) => { camRef.current = { ...M3_VIEWS[k] }; setView(k); };
  const clock = `${Math.min(90, Math.floor(minute))}'`;

  return (
    <Modal onClose={onClose}>
      <div className="lr-m3">
        <h2>3D-Ansicht</h2>
        <div className="lr-m3-hud" id="m3-hud">
          <span className="lr-m3-t r"><span>{spec.home.name}</span><Logo name={spec.home.name} /></span>
          <b className="lr-m3-sc" id="m3-score">{sh}:{sa}</b>
          <span className="lr-m3-t"><Logo name={spec.away.name} /><span>{spec.away.name}</span></span>
          <span className="lr-m3-min" id="m3-min">{done ? "Abpfiff" : minute < 0.2 && !running ? "Anstoß" : clock}</span>
        </div>
        <div className="lr-m3-stage" ref={wrapRef}>
          <canvas ref={canvasRef} id="m3-canvas" aria-label="3D-Ansicht des Spiels" />
          {lastGoal && (
            <div className="lr-m3-goal" id="m3-goal">
              TOR! {goalsNow.filter((g) => g.t === "h").length}:{goalsNow.filter((g) => g.t === "a").length}
              <small>{(lastGoal.p ? `${lastGoal.p} · ` : "") + (lastGoal.t === "h" ? spec.home.name : spec.away.name)} · {Math.round(lastGoal.at)}'</small>
            </div>
          )}
        </div>
        <div className="lr-m3-bar">
          <button className="lr-btn lr-btn-p" id="m3-play" onClick={toggle}>{running ? "Pause" : done ? "Nochmal" : minute > 0.2 ? "Weiter" : "Anpfiff"}</button>
          <input type="range" id="m3-seek" min="0" max="90" step="0.5" value={Math.min(90, minute)} aria-label="Spielminute"
            onChange={(e) => seek(Number(e.target.value))} />
          <label className="lr-m3-lab">Tempo
            <select className="lr-jump" id="m3-speed" value={speed} onChange={(e) => setSpeed(Number(e.target.value))}>
              <option value={0.5}>0,5×</option><option value={1}>1×</option><option value={2}>2×</option><option value={4}>4×</option>
            </select>
          </label>
          <label className="lr-m3-lab">Kamera
            <select className="lr-jump" id="m3-view" value={view} onChange={(e) => pickView(e.target.value)}>
              {Object.entries(M3_VIEWS).map(([k, v]) => <option key={k} value={k}>{v.name}</option>)}
              {view === "frei" && <option value="frei">Frei</option>}
            </select>
          </label>
        </div>
        <p className="lr-hint" style={{ margin: "10px 0 6px" }}>
          Maus ziehen dreht die Kamera, Mausrad zoomt. {game.open ? "Dieses Spiel ist noch offen: es wurde ausgewürfelt und ist erst gespeichert, wenn du es übernimmst." : "Die Tore fallen in den eingetragenen Minuten."}
          {spec.note ? ` ${spec.note}` : ""}
        </p>
        <div className="lr-m3-goals" id="m3-goals">
          {!data.tl.goals.length && <span className="lr-empty">Keine Tore.</span>}
          {data.tl.goals.map((g, i) => (
            <button key={i} className="lr-m3-gl" type="button" onClick={() => seek(g.at - 2.2)} data-on={g.at <= minute ? "1" : "0"}>
              <b>{Math.round(g.at)}'</b> {g.p || "Tor"} <small>{g.t === "h" ? spec.home.name : spec.away.name}</small>
            </button>
          ))}
        </div>
        <div className="lr-modal-foot">
          <button className="lr-btn" onClick={onClose}>Schließen</button>
          {game.open && spec.onTake && (
            <button className="lr-btn lr-btn-p" id="m3-take" onClick={() => { spec.onTake(game.hg, game.ag, game.sc); onClose(); }}>
              Ergebnis {game.hg}:{game.ag} übernehmen
            </button>
          )}
        </div>
      </div>
    </Modal>
  );
}

/* ---------------- Liveticker ---------------- */

/** Ein Spiel dauert im Ticker zwei Minuten Echtzeit (= 90 Spielminuten). */
const LIVE_SECONDS = 120;

/** Fehlende Torschützen mit Minute auffüllen, damit der Ticker immer zum Endstand passt. */
function liveGoals(sc, hg, ag) {
  const out = (sc || []).map((g) => ({ ...g, m: g.m || 1 + Math.floor(Math.random() * 90) }));
  [["h", hg], ["a", ag]].forEach(([t, n]) => {
    for (let k = out.filter((g) => g.t === t).length; k < n; k++) out.push({ t, p: "", m: 1 + Math.floor(Math.random() * 90) });
  });
  return out.sort((x, y) => x.m - y.m);
}

function LiveTicker({ games, season, fixtures, mdIdx, onClose, onFinish }) {
  const [elapsed, setElapsed] = useState(0);
  const [running, setRunning] = useState(false);
  const last = useRef(0);

  useEffect(() => {
    if (!running) return undefined;
    last.current = Date.now();
    const id = setInterval(() => {
      const now = Date.now();
      const dt = (now - last.current) / 1000;
      last.current = now;
      setElapsed((e) => Math.min(LIVE_SECONDS, e + dt));
    }, 200);
    return () => clearInterval(id);
  }, [running]);

  const done = elapsed >= LIVE_SECONDS;
  useEffect(() => { if (done) setRunning(false); }, [done]);
  const minute = done ? 90 : Math.floor((elapsed / LIVE_SECONDS) * 90);

  // Torfolge je Spiel mit laufendem Zwischenstand.
  const events = useMemo(() => games.flatMap((g, gi) => {
    let h = 0, a = 0;
    return [...g.sc].sort((x, y) => x.m - y.m).map((e) => {
      if (e.t === "h") h++; else a++;
      return { m: e.m, gi, e, score: `${h}:${a}` };
    });
  }).sort((x, y) => x.m - y.m), [games]);

  const stand = (gi) => {
    const sofar = events.filter((x) => x.gi === gi && x.m <= minute);
    const h = sofar.filter((x) => x.e.t === "h").length;
    return { h, a: sofar.length - h };
  };

  const res = { ...season.results };
  if (minute >= 1) games.forEach((g, gi) => { const st = stand(gi); res[`${mdIdx}:${g.gi}`] = { h: String(st.h), a: String(st.a) }; });
  const rows = computeTable(season.teams, fixtures, res);
  const shown = events.filter((x) => x.m <= minute).reverse();
  const clock = (sec) => `${Math.floor(sec / 60)}:${String(Math.floor(sec % 60)).padStart(2, "0")}`;

  return (
    <Modal onClose={elapsed > 0 && !done ? () => {} : onClose}>
      <div className="lr-live">
        <h2>Liveticker — {mdIdx + 1}. Spieltag</h2>
        <p>
          Alle offenen Spiele laufen gleichzeitig, ein Spiel dauert zwei Minuten. Die Ergebnisse
          werden erst gespeichert, wenn du sie am Ende übernimmst.
        </p>
        <div className="lr-live-bar">
          <span className="lr-live-min" id="live-min">{done ? "Abpfiff" : `${minute}. Minute`}</span>
          <div className="lr-live-track"><div style={{ width: `${(elapsed / LIVE_SECONDS) * 100}%` }} /></div>
          <span className="lr-status">{clock(elapsed)} / {clock(LIVE_SECONDS)}</span>
        </div>
        <div className="lr-live-grid">
          <div>
            <div className="lr-pl-sec"><span>Spiele</span></div>
            {games.map((g, gi) => {
              const st = stand(gi);
              const treffer = events.some((x) => x.gi === gi && x.m <= minute && x.m > minute - 3);
              return (
                <div className="lr-live-game" key={g.gi} data-goal={treffer && !done ? "1" : "0"}>
                  <span className="lr-live-t r"><span>{season.teams[g.h]}</span><Logo name={season.teams[g.h]} /></span>
                  <b className="lr-live-sc">{minute < 1 ? "–" : `${st.h}:${st.a}`}</b>
                  <span className="lr-live-t"><Logo name={season.teams[g.a]} /><span>{season.teams[g.a]}</span></span>
                </div>
              );
            })}
            <div className="lr-pl-sec" style={{ marginTop: 14 }}><span>Torfolge</span></div>
            <div className="lr-live-feed" id="live-feed">
              {!shown.length && <p className="lr-empty">Noch kein Tor gefallen.</p>}
              {shown.map((x, i) => (
                <div key={i} className="lr-live-ev">
                  <b>{x.m}'</b>
                  <span>Tor {season.teams[x.e.t === "h" ? games[x.gi].h : games[x.gi].a]}{x.e.p ? ` — ${x.e.p}` : ""}</span>
                  <small>{season.teams[games[x.gi].h]} {x.score} {season.teams[games[x.gi].a]}</small>
                </div>
              ))}
            </div>
          </div>
          <div>
            <div className="lr-pl-sec"><span>Tabelle live</span></div>
            <table className="lr-live-tab">
              <thead><tr><th>#</th><th>Mannschaft</th><th>Sp</th><th>Diff</th><th>Pkt</th></tr></thead>
              <tbody>
                {rows.map((r, i) => (
                  <tr key={r.name}>
                    <td>{i + 1}</td>
                    <td><Logo name={r.name} />{r.name}</td>
                    <td>{r.sp}</td>
                    <td>{r.diff > 0 ? `+${r.diff}` : r.diff}</td>
                    <td><b>{r.pkt}</b></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
        <div className="lr-modal-foot">
          <button className="lr-btn" onClick={onClose}>Abbrechen</button>
          {!done && (
            <button className="lr-btn" id="live-skip" onClick={() => { setElapsed(LIVE_SECONDS); setRunning(false); }}>Sofort beenden</button>
          )}
          {!done && (
            <button className="lr-btn lr-btn-p" id="live-start" onClick={() => setRunning((r) => !r)}>
              {running ? "Pause" : elapsed > 0 ? "Weiter" : "Anpfiff"}
            </button>
          )}
          {done && <button className="lr-btn lr-btn-p" id="live-take" onClick={onFinish}>Ergebnisse übernehmen</button>}
        </div>
      </div>
    </Modal>
  );
}

/* ---------------- England im Europapokal ---------------- */

/** Wie weit ist ein Klub im laufenden Europapokal? Ohne laufende Runde: qualifiziert. */
function euroClubStatus(run, name) {
  if (!run) return "qualifiziert, Runde noch nicht gestartet";
  const idx = run.teams.findIndex((t) => t.name === name);
  if (idx < 0) return "in dieser Runde nicht dabei";
  const row = euroTable(run).find((r) => r.idx === idx);
  const phase = `Ligaphase: Platz ${row.pos}, ${row.pkt} Punkte nach ${row.sp} Spielen`;
  if (!run.ko.length) return phase;
  let status = null;
  for (const rd of run.ko) {
    const two = rd.name !== "Finale";
    const tie = rd.ties.find((t) => t.h === idx || t.a === idx);
    if (!tie) continue;
    const w = tieWinner(tie, two);
    if (!w) { status = `spielt im ${rd.name}`; break; }
    if ((w === "h" ? tie.h : tie.a) !== idx) { status = `ausgeschieden im ${rd.name}`; break; }
    status = rd.name === "Finale" ? "Sieger" : `${rd.name} gewonnen`;
  }
  if (!status) status = row.pos <= 8 ? "direkt im Achtelfinale" : "ausgeschieden in der Ligaphase";
  return `${phase} · ${status}`;
}

/** Welche Klubs eines Landes spielen in CL, EL und ECL, und wer qualifiziert sich nach der aktuellen Tabelle? */
function CountryEuropa({ data, cty }) {
  const top = data.active[cty.top];
  const gespielt = Object.keys(top.results).length > 0;
  const tabelle = computeTable(top.teams, makeFixtures(top.teams.length, top.seed), top.results).map((r) => r.name);
  const spaeter = euroQualifiersEn(tabelle, euroPlaces(data.euro.teams, cty.flag, cty.places));
  const p = cty.places;
  return (
    <div className="lr-wrap">
      <section style={accentVars("#4C8BF5")}>
        <h2>Europapokal — {cty.name}</h2>
        <p className="lr-hint">
          Diese Klubs der {cty.topName} spielen in der Europapokal-Saison mit. Stärke und Kader kommen
          live aus der Liga. Für die nächste Saison zählt die Tabelle der {cty.topName}: Plätze
          {" "}1–{p.cl} Champions League, {p.cl + 1}–{p.cl + p.el} Europa League,
          {" "}{p.cl + p.el + 1}{p.ecl > 1 ? `–${p.cl + p.el + p.ecl}` : ""} Conference League.
        </p>
        <div className="lr-top-grid">
          {EURO_COMPS.map((c) => {
            const liste = (data.euro.teams[c.id] || []).filter((t) => t[cty.flag]);
            const run = data.euro.runs[c.id];
            return (
              <div key={c.id} data-comp={c.id}>
                <div className="lr-top-h" style={{ "--accent": c.accent }}>
                  <b>{c.name}</b>
                  <span>{liste.length} aus {cty.name}</span>
                </div>
                <ol className="eu-eng">
                  {liste.map((t, i) => (
                    <li key={t.name}>
                      <span className="eu-n">{i + 1}</span>
                      <span className="eu-nm"><Logo name={t.name} />{t.name}</span>
                      <span className="eu-s">{euroStrength(t, data.active)}</span>
                      <small>{euroClubStatus(run, t.name)}</small>
                    </li>
                  ))}
                </ol>
                {gespielt && spaeter[c.id].length > 0 && (
                  <p className="lr-hint" style={{ marginTop: 10 }}>
                    Nach der aktuellen Tabelle in der nächsten Saison: {spaeter[c.id].join(", ")}.
                  </p>
                )}
              </div>
            );
          })}
        </div>
      </section>
    </div>
  );
}

/* ================================================================== */
/*  Kalender                                                          */
/* ================================================================== */

function Kalender({ data, onJump, section }) {
  const [filter, setFilter] = useState("alle");

  const events = useMemo(() => {
    const out = [];
    const eng = section !== "de";
    COUNTRY[section].ids.forEach((id) => {
      const s = data.active[id];
      const count = s.teams.length * 2 - 2;
      matchdayDates(s.start, count).forEach((d, i) => {
        out.push({ date: d, comp: id, name: LEAGUE_BY_ID[id].name, accent: LEAGUE_BY_ID[id].accent, idx: i, what: `${i + 1}. Spieltag` });
      });
    });
    if (eng && data[COUNTRY[section].cupKey]) {
      const cu = data[COUNTRY[section].cupKey];
      cu.rounds.forEach((r, i) => {
        out.push({ date: cupRoundDate(cu.label, i, COUNTRY[section].cupKey), comp: COUNTRY[section].cupKey, name: COUNTRY[section].cupName, accent: COUNTRY[section].cupAccent, idx: i, what: r.name });
      });
    }
    if (!eng && data.cup) {
      data.cup.rounds.forEach((r, i) => {
        out.push({ date: cupRoundDate(data.cup.label, i, "cup"), comp: "cup", name: "DFB-Pokal", accent: CUP_ACCENT, idx: i, what: r.name });
      });
    }
    if (!eng) {
      EURO_COMPS.forEach((c) => {
        const run = data.euro && data.euro.runs[c.id];
        euroEvents(c.id, run ? run.label : data.active.bl1.label).forEach((e) => out.push(e));
      });
    }
    return out.sort((a, b) => a.date - b.date);
  }, [data, section]);

  const shown = filter === "alle" ? events : events.filter((e) => e.comp === filter);

  const months = [];
  shown.forEach((e) => {
    const key = `${e.date.getFullYear()}-${e.date.getMonth()}`;
    const last = months[months.length - 1];
    if (last && last.key === key) last.items.push(e);
    else months.push({ key, title: `${MONTHS[e.date.getMonth()]} ${e.date.getFullYear()}`, items: [e] });
  });

  return (
    <>
      <div className="lr-bar">
        <h2 className="disp" style={{ fontSize: 20 }}>Kalender</h2>
        <div className="lr-spacer" />
        <label className="lr-prog" style={{ display: "flex", alignItems: "center", gap: 5 }}>
          Wettbewerb
          <select className="lr-jump" value={filter} onChange={(e) => setFilter(e.target.value)}
            aria-label="Wettbewerb filtern">
            <option value="alle">alle</option>
            {COUNTRY[section].leagues.map((l) => <option key={l.id} value={l.id}>{l.name}</option>)}
            <option value={COUNTRY[section].cupKey}>{COUNTRY[section].cupName}</option>
            {section === "de" && EURO_COMPS.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
          </select>
        </label>
      </div>

      <p className="lr-hint" style={{ paddingBottom: 12 }}>
        {section !== "de"
          ? `Alle Termine der ${COUNTRY[section].topName}, nach Monat sortiert. Der Spielplan folgt demselben
        Rhythmus wie in Deutschland: Pause vom 20. Dezember bis zum 9. Januar und in den vier
        Länderspielpausen im September, Oktober, November und März. Ein Klick springt zum Spieltag.`
          : `Alle Termine der Saison, nach Monat sortiert. Gespielt wird nicht über die
        Winterpause vom 20. Dezember bis zum 9. Januar und nicht in den vier
        Länderspielpausen im September, Oktober, November und März. Die Europapokale
        spielen dienstags (Champions League) und donnerstags (Europa und Conference League).
        Ein Klick springt zum Spieltag.`}
      </p>

      {months.map((m) => (
        <div className="lr-cal-month" key={m.key}>
          <h3>{m.title}</h3>
          {m.items.map((e, i) => (
            <button className="lr-cal-row" key={i} onClick={() => onJump(e.comp, e.idx, e)}>
              <span className="lr-cal-bar" style={{ background: e.accent }} />
              <span className="lr-cal-date">{fmtShort(e.date)}</span>
              <span className="lr-cal-what">{e.what}</span>
              <span className="lr-cal-comp">{e.name}</span>
            </button>
          ))}
        </div>
      ))}
    </>
  );
}

/* ================================================================== */
/*  Historie                                                          */
/* ================================================================== */

function Historie({ history, open, setOpen, onExport, onBackup, onReset, onPromotion, onRestart, section }) {
  const [filter, setFilter] = useState("all");
  const titles = useMemo(() => {
    const out = { cup: {}, facup: {}, copa: {}, coppa: {}, coupe: {}, tournko: {}, cl: {}, el: {}, ecl: {} };
    [...LEGACY_LEAGUES, ...LEAGUES, ...ENGLAND, ...SPAIN, ...ITALY, ...FRANCE, ...WORLD_LEAGUES].forEach((l) => { out[l.id] = {}; });
    WORLD.forEach((c) => { out[c.cup.key] = {}; });
    history.forEach((h) => {
      if (h.type === "euro") {
        if (h.winner && h.winner !== "—" && out[h.leagueId]) out[h.leagueId][h.winner] = (out[h.leagueId][h.winner] || 0) + 1;
        return;
      }
      if (h.type === "cup") {
        if (h.winner && out[h.leagueId]) out[h.leagueId][h.winner] = (out[h.leagueId][h.winner] || 0) + 1;
        return;
      }
      const first = h.table && h.table[0];
      if (!first || !out[h.leagueId]) return;
      out[h.leagueId][first.name] = (out[h.leagueId][first.name] || 0) + 1;
    });
    return out;
  }, [history]);

  const boards = (section !== "de"
    ? [...COUNTRY[section].leagues.map((l) => ({ key: l.id, accent: l.accent, head: `Meisterschaften — ${l.name}` })),
      { key: COUNTRY[section].cupKey, accent: COUNTRY[section].cupAccent, head: `Pokalsiege — ${COUNTRY[section].cupName}` }]
    : [
      ...[...LEAGUES, ...LEGACY_LEAGUES].map((l) => ({
        key: l.id, accent: l.accent,
        head: `${l.id === "bl1" ? "Meisterschaften" : "Titel"} — ${l.name}`,
      })),
      { key: "cup", accent: CUP_ACCENT, head: "Pokalsiege — DFB-Pokal" },
      ...EURO_COMPS.map((c) => ({ key: c.id, accent: c.accent, head: `Titel — ${c.name}` })),
    ]).filter((b) => Object.keys(titles[b.key]).length > 0);

  /** Einträge nach Wettbewerb ordnen, jeweils die neueste Saison zuerst. */
  const groups = useMemo(() => {
    const defs = section !== "de"
      ? [...COUNTRY[section].leagues.map((l) => ({ key: l.id, name: l.name, accent: l.accent })), { key: COUNTRY[section].cupKey, name: COUNTRY[section].cupName, accent: COUNTRY[section].cupAccent }]
      : [
        ...[...LEAGUES, ...LEGACY_LEAGUES].map((l) => ({ key: l.id, name: l.name, accent: l.accent })),
        { key: "cup", name: "DFB-Pokal", accent: CUP_ACCENT },
        ...EURO_COMPS.map((c) => ({ key: c.id, name: c.name, accent: c.accent })),
      ];
    const keyOf = (h) => h.leagueId;
    return defs
      .map((d) => ({
        ...d,
        items: history
          .filter((h) => keyOf(h) === d.key)
          .sort((a, b) => String(b.label).localeCompare(String(a.label)) || String(b.closedAt).localeCompare(String(a.closedAt))),
      }))
      .filter((d) => d.items.length > 0);
  }, [history]);

  return (
    <>
      <div className="lr-bar">
        <h2 className="disp" style={{ fontSize: 20 }}>Historie</h2>
        <div className="lr-spacer" />
        {section === "de" && <button className="lr-btn lr-btn-sm" onClick={onPromotion}>Alle Ligen abschließen</button>}
        <button className="lr-btn lr-btn-sm" id="backup-open" onClick={onBackup}>Sichern</button>
        <button className="lr-btn lr-btn-sm" onClick={onExport}>Exportieren</button>
        <button className="lr-btn lr-btn-sm" onClick={onRestart}>Neu beginnen</button>
        <button className="lr-btn lr-btn-sm" onClick={onReset}>Alles zurücksetzen</button>
      </div>

      {!history.length && (
        <p className="lr-empty">
          Noch keine abgeschlossene Saison. Sobald du eine Liga oder den Pokal abschließt,
          landet das Ergebnis hier und bleibt dauerhaft gespeichert.
        </p>
      )}

      {boards.length > 0 && (
        <div className="lr-titles" style={{ marginTop: 26 }}>
          {boards.map((b) => {
            const entries = Object.entries(titles[b.key])
              .sort((x, y) => y[1] - x[1] || x[0].localeCompare(y[0], "de"));
            return (
              <div key={b.key}>
                <h3 style={{ borderBottomColor: b.accent }}>{b.head}</h3>
                <ol>
                  {entries.map(([name, count]) => (
                    <li key={name}><span>{name}</span><span>{count}×</span></li>
                  ))}
                </ol>
              </div>
            );
          })}
        </div>
      )}

      {history.length > 0 && (
        <div className="lr-rounds" style={{ paddingTop: 18 }}>
          <button className="lr-round-btn" data-on={filter === "all" ? "1" : "0"} onClick={() => setFilter("all")}>Alle</button>
          {groups.map((g) => (
            <button key={g.key} className="lr-round-btn" data-on={filter === g.key ? "1" : "0"}
              style={filter === g.key ? accentVars(g.accent) : undefined} onClick={() => setFilter(g.key)}>
              {g.name} · {g.items.length}
            </button>
          ))}
        </div>
      )}

      {groups.filter((g) => filter === "all" || filter === g.key).map((g) => (
      <div key={g.key} className="lr-hist-group">
      <h3 className="lr-hist-group-h" style={{ borderBottomColor: g.accent }}>{g.name}</h3>
      {g.items.map((h) => {
        const isEuro = h.type === "euro";
        const isCup = h.type === "cup" || isEuro;
        const l = LEAGUE_BY_ID[h.leagueId];
        const accent = isEuro && EURO_BY_ID[h.leagueId] ? EURO_BY_ID[h.leagueId].accent : isCup ? CUP_ACCENT : l ? l.accent : "#C9C3B0";
        const isOpen = open === h.id;
        const champ = isCup ? h.winner : h.table && h.table[0] ? h.table[0].name : "—";
        return (
          <div key={h.id}>
            <button className="lr-hist-row" onClick={() => setOpen(isOpen ? null : h.id)}>
              <span className="lr-hist-season">{h.label}</span>
              <span className="lr-hist-league" style={{ color: accent }}>{h.leagueName}</span>
              <span className="lr-hist-champ">
                <b>{champ}</b>
                {!isCup && h.table && h.table[0] ? (
                  <span style={{ color: "#96A093" }}> · {h.table[0].pkt} Punkte</span>
                ) : null}
              </span>
              <span className="lr-hist-open">{isOpen ? "schließen" : isCup ? "Turnierbaum" : "Tabelle"}</span>
            </button>
            {isOpen && (
              <div className="lr-hist-body" style={accentVars(accent)}>
                {isEuro && h.table ? (
                  <div style={{ marginBottom: 14 }}>
                    <div className="lr-duel-h">Tabelle der Ligaphase</div>
                    <Table rows={h.table} leagueId="eu" compact />
                  </div>
                ) : null}
                {isCup ? (
                  <div className="lr-bracket">
                    {h.rounds.map((r) => (
                      <div key={r.name}>
                        <h4>{r.name}</h4>
                        {r.games.map((g, i) => (
                          <div className="g" key={i}>
                            <span>{g.h}</span>
                            <b>{g.hg}:{g.ag}{g.pen ? " n.E." : ""}</b>
                            <span>{g.a}</span>
                          </div>
                        ))}
                      </div>
                    ))}
                  </div>
                ) : (
                  <Table rows={h.table} leagueId={h.leagueId} compact />
                )}
                {h.type === "league" && h.unbeaten && h.unbeaten.length ? (
                  <div className="lr-duel-h" style={{ marginTop: 12 }}>
                    Längste Serie ohne Niederlage: {h.unbeaten[0].name}, {h.unbeaten[0].len} Spiele
                    ({h.unbeaten[0].from === h.unbeaten[0].to ? `${h.unbeaten[0].from}. Spieltag` : `${h.unbeaten[0].from}.–${h.unbeaten[0].to}. Spieltag`})
                  </div>
                ) : null}
                {h.scorers && h.scorers.length ? (
                  <div style={{ marginTop: 12 }}>
                    <div className="lr-duel-h">
                      Torschützenkönig: {h.scorers[0].name} ({h.scorers[0].verein}), {h.scorers[0].tore} Tore
                    </div>
                    <table className="lr-top-tbl">
                      <colgroup><col className="r" /><col /><col /><col className="g" /></colgroup>
                      <thead><tr><th /><th>Spieler</th><th className="v">Verein</th><th className="g">Tore</th></tr></thead>
                      <tbody>
                        {h.scorers.map((e, i) => (
                          <tr key={e.name + e.verein}>
                            <td className="r">{i + 1}</td>
                            <td>{e.name}</td>
                            <td className="v">{e.verein}{e.vorher ? <span className="vor">{e.vorher}</span> : null}</td>
                            <td className="g">{e.tore}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                ) : null}
              </div>
            )}
          </div>
        );
      })}
      </div>
      ))}
    </>
  );
}


